LESSONS.explodeChain67={title:'Explode：两波连锁与模型移除',kind:'N5.3 · Explode',source:'https://infinitythewiki.com/Explode',terrain:[],positions:[[20,30],[20,28]],overrides:[{name:'红方连锁自爆体',explode:true,attribute:'STR',hp:1,maxhp:1,arm:0},{name:'蓝方首个自爆体',explode:true,attribute:'STR',hp:1,maxhp:1,arm:0}],equipment:{a0:{loadout:['combi','cc'],weapon:'combi'}},extras:[{id:'chain-last',name:'蓝方末端目标',team:1,x:20,y:32,z:0,hp:2,maxhp:2,arm:0,courage:true,explode:false,attribute:'STR',loadout:['combi','cc'],weapon:'combi',facing:-90}],instructions:'红方待机 → 蓝方均放弃 → 复合步枪射击前方自爆体，固定5/20/20仅一命中 → 过保20昏迷 → 第1波炸昏红方 → 第2波炸伤末端目标。两源逐波移除，最后才勇气。',dice:[5,20,20,20,20,20]};
LESSONS.explodeFriendly67={...LESSONS.explodeChain67,title:'Explode：覆盖友军取消但自爆者仍移除',extras:[{...LESSONS.explodeChain67.extras[0],name:'蓝方友军保护测试',x:22,y:28}],instructions:'射击蓝方自爆体使其昏迷 → 自爆范围包含蓝方友军，攻击取消，无自爆过保，源仍被移除。',dice:[5,20,20,20]};
LESSONS.explodeDead67={...LESSONS.explodeChain67,title:'Explode：直接移除不触发',extras:[],instructions:'复合步枪两发命中，过保均失败：1STR单位直接Dead，不进入自爆阶段。',dice:[5,6,20,20,20]};
