LESSONS.explodeDodge67={...LESSONS.explodeChain67,title:'Explode：沿用本命令闪避骰',overrides:[{...LESSONS.explodeChain67.overrides[0],ph:12},{...LESSONS.explodeChain67.overrides[1],explode:false,ph:12}],extras:[],instructions:'红方首项待机 → 蓝方复合步枪射击ARO → 红方第二项闪避，7成功但被更高射击骰10压过；过保失败使红方昏迷。自爆时蓝方未闪避仍须过保。换成红方射击、蓝方闪避可验证已有闪避成功骰避免自爆。',dice:[7,10,20,20]};
LESSONS.explodeDodge67={...LESSONS.explodeChain67,title:'Explode：沿用第三方闪避骰',overrides:[{...LESSONS.explodeChain67.overrides[0],ph:12},{...LESSONS.explodeChain67.overrides[1],explode:false,hp:3,maxhp:3,courage:true}],extras:[{...LESSONS.explodeChain67.extras[0],name:'已闪避的第三方',hp:3,maxhp:3,ph:12}],instructions:'红方待机 → 前方蓝体射击ARO，后方第三人Dodge → 红方第二项Dodge。红20失败，蓝7命中，第三人5闪避成功先原地结束闪避移动。过保20使红体昏迷，自爆只让射击者过保；第三人沿用5避开，不再掷骰。',dice:[20,7,5,20,1]};
