LESSONS.protheionARO72={...LESSONS.protheion72,title:'Protheion：反应近战吸取',overrides:[{name:'主动近战目标',cc:15,arm:0},{name:'反应吸取者（教学）',cc:20,protheion:true,protheionMod:-3}],instructions:'红方待机 → 蓝方近战ARO并启用Protheion → 红方近战。红骰6对蓝骰12，蓝方获胜，红方过保20失败；蓝方VITA提高到2。',dice:[6,12,20]};

Object.assign(LESSONS.specGrenade71,{kind:'N5.3 · p48',question:'隔墙榴弹如何计算？',answer:'推测攻击是主动整令，B1，只应用−6、距离及正向修正。圆模板可偏移，但必须覆盖主目标；敌人逐个反应。'});Object.assign(LESSONS.specOffset71,{kind:'N5.3 · p48',question:LESSONS.specGrenade71.question,answer:LESSONS.specGrenade71.answer});
LESSONS.bangbomb73={title:'Bangbomb：同一闪避骰避枪但不避模板',kind:'N5.3 · p120',source:'https://infinitythewiki.com/Bangbomb',reviewDate:'2026-10-23',question:'Bangbomb +4是否对所有攻击有效？',answer:'仅对视线或控制区内敌人的非模板攻击生效。同一颗闪避骰对每项攻击分别计算；未避开其中一项就不能闪避移动。',positions:[[20,28],[18,24]],terrain:[],overrides:[{name:'Bangbomb教学',ph:13,bangbomb:4,hp:3,maxhp:3,courage:true},{name:'步枪反应者',bs:11}],equipment:{a0:{loadout:['combi'],weapon:'combi'},b0:{loadout:['combi'],weapon:'combi'}},extras:[{id:'bang-template',bangbomb:0,name:'模板反应者',team:1,x:22,y:24,z:0,facing:90,loadout:['heavyFlame'],weapon:'heavyFlame',trainingWeapon:true}],instructions:'待机 → 蓝方分别复合步枪/重喷ARO → 主动方Dodge。闪避14对步枪SV17成功，对模板SV13失败；只有模板过保，不能闪避移动。',dice:[14,9,1]};
LESSONS.bangbombARO73={...LESSONS.bangbomb73,title:'Bangbomb：反应轮闪避与主动射击',positions:[[20,28],[20,24]],extras:[],overrides:[{name:'主动射手',bs:10},{name:'Bangbomb反应者',ph:13,bangbomb:4}],instructions:'待机 → 蓝方Dodge，勾选Bangbomb → 红方复合步枪射击。反应闪避14在SV17成功，抵消三发9/10/11；进入闪避移动。',dice:[9,10,11,14]};
LESSONS.symbioMate74={title:'SymbioMate：强制防护与命令末消耗',kind:'N5.3 · p126',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/SymbioMate',question:'共生防护是永久ARM9吗？',answer:'不是。被迫过保时本命令使用ARM/BTS9和增强免疫，命令结束消耗；通讯攻击只使用BTS9，不享受增强免疫。',positions:[[20,28],[20,24]],terrain:[],overrides:[{name:'穿爆教学射手',bs:14},{name:'共生防护使用者',hp:4,maxhp:4,arm:1,bts:3,symbioMate:{ownerId:'training'},transmutation:{threshold:1},courage:true}],equipment:{a0:{loadout:['lab'],weapon:'lab',modeId:'AP+EXP'},b0:{loadout:['combi'],weapon:'combi'}},weapon:'lab',modeId:'AP+EXP',instructions:'待机→对方放弃→AP+EXP射击。第一令只有1次ARM9过保，完成后装备消失；再射击则恢复3次ARM减半过保。',dice:[8,20,1,1]};
LESSONS.symbioComms74={...LESSONS.symbioMate74,title:'SymbioMate：通讯攻击不享受增强免疫',overrides:[{name:'聚光黑客',hackingDevice:'HD',wip:13},{...LESSONS.symbioMate74.overrides[1]}],equipment:{a0:{loadout:['combi'],weapon:'combi'},b0:{loadout:['combi'],weapon:'combi'}},weapon:'combi',modeId:'hit',instructions:'待机→对方Reset→黑客Spotlight。成功后BTS9仍按AP减半，失败进入Targeted；装备在命令末消耗。',dice:[8,9,20,20,20]};

LESSONS.symbioAssign74={title:'共生装备：部署时分配给合格模型',kind:'N5.3 · Assignable',source:'https://infinitythewiki.com/Labels',reviewDate:'2026-10-23',question:'可否在游戏中随时换持有者？',answer:'只能部署拥有者时分配；同军表场上Transmutation(X)模型，每类最多一件，标记或桌外模型不合格。',positions:[[20,40],[20,5]],terrain:[],overrides:[{name:'共生装备拥有者',symbioMateStock:2,symbioBombStock:2},{name:'敌方模型'}],extras:[{id:'symbio-user',name:'合格共生模型',team:0,x:23,y:40,transmutation:{threshold:1},symbioMateStock:0,symbioBombStock:0},{id:'symbio-marker',name:'迷彩不合格模型',team:0,x:26,y:40,transmutation:{threshold:1},states:['camouflaged'],symbioMateStock:0,symbioBombStock:0}],pregame:{stage:'deploy',firstDeployment:0,step:0,reserves:{0:[],1:[]},sides:{0:'south',1:'north'}},editableDeploy:true,instructions:'拥有者右侧仅合格共生模型可选，分别分配Mate和Bomb；各类只能一件，分配后选项为空，库存剩1。地图显示两个紧凑状态标记。',dice:[1]};
LESSONS.symbioBomb75={title:'SymbioBomb：隔墙Endgame对Reset',kind:'N5.3 · p74 / Weapon Chart',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/SymbioBomb',question:'共生炸弹需要黑客装置或视线吗？',answer:'已分配炸弹提供Endgame、Eraser和Mirrorball；攻击战术只针对本人控制区内VITA模型，不经中继器。可主动短技能或ARO，Endgame/Eraser对拼骰目标−3。一次使用后命令末移除。',positions:[[20,28],[20,24]],terrain:[{id:'pt-wall',x:18,y:25.5,w:4,h:.3,height:2,name:'隔墙',kind:'wall'}],overrides:[{name:'共生炸弹教学',symbioBomb:{ownerId:'training'},wip:13},{name:'VITA目标',hp:3,maxhp:3,bts:3,courage:true}],equipment:{a0:{loadout:['cc'],weapon:'cc'},b0:{loadout:['combi'],weapon:'combi'}},instructions:'待机→对方Reset→通讯攻击，选择Endgame Double Shot主动B2。8/9对Reset20（SV10），两次BTS/2过保，受1伤；命令末炸弹消失。',dice:[8,9,20,20,1]};
LESSONS.symbioEraserARO75={...LESSONS.symbioBomb75,title:'SymbioBomb：无视线Eraser ARO',overrides:[{name:'主动VITA目标',hp:3,maxhp:3,bts:3},{name:'Eraser反应者',symbioBomb:{ownerId:'training'},wip:13}],instructions:'主动待机→蓝方Eraser ARO（B1）→主动Reset。Reset20对Eraser8，两次DA/BTS过保20/1；只孤立，不掉生命；炸弹消耗。',dice:[20,8,20,1]};
LESSONS.symbioMirrorball75={...LESSONS.symbioBomb75,title:'SymbioBomb：Mirrorball隔墙放置Eclipse',instructions:'待机→蓝方放弃→投掷/发射，选择Mirrorball并在墙另一侧指定落点。本人控制区内WIP成功后出现Eclipse，炸弹命令末移除；ARO使用仍需要看到主动模型。',dice:[8]};
LESSONS.transAuto76={title:'变形：换大底盘，边缘匹配后移动',kind:'N5.3 · p22 / p118 Auto',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/Replacing_Game_Elements',question:'换底盘能保持贴墙吗？',answer:'不同底径可选择中心或边缘匹配；不能借此解除交战。Auto在移动开始时切换，使用新形态MOV，伤口和状态共享。',positions:[[20,28],[35,10]],terrain:[{id:'transform-wall',x:18,y:25,w:1.5,h:8,height:4,name:'贴墙换底盘',kind:'wall'}],overrides:[{name:'自动变形教学',transmutation:{type:'auto',profiles:[{s:2,mov:4},{s:6,mov:6}]}},{}],first:'move',instructions:'开始Move→中心匹配受墙阻挡；选边缘匹配，角度180使底盘仍贴左侧墙→确认。新形态MOV6；可移动并完成ARO/第二项。',dice:[1]};
LESSONS.transCramped76={title:'变形：狭窄空间强制替换与特殊IMM-A',kind:'N5.3 · p22 / p118',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/Transmutation',question:'强制变形但新轮廓放不下怎么办？',answer:'无法容纳时强制替换并进入IMM-A；这种IMM-A不能用闪避解除，只在空间条件改变后解除。',positions:[[20,28],[20,24]],terrain:[{id:'narrow-t1',x:18,y:21,w:1.5,h:5,height:4,name:'窄室左墙',kind:'wall'},{id:'narrow-t2',x:20.5,y:21,w:1.5,h:5,height:4,name:'窄室右墙',kind:'wall'}],overrides:[{name:'变形测试射手',bs:14},{name:'强制变形模型',hp:3,maxhp:3,courage:true,transmutation:{threshold:1,profiles:[{s:2},{s:6}]}}],equipment:{a0:{loadout:['lab'],weapon:'lab'},b0:{loadout:['combi'],weapon:'combi'}},weapon:'lab',modeId:'N',instructions:'待机→目标放弃→普通N射击，8命中、20过保失败。勇气自动成功后出现形态替换；全部对齐均受限，确认后S6、IMM-A。下一回合成功闪避也不能解除此状态。',dice:[8,20]};
LESSONS.transEscape76={...LESSONS.transCramped76,title:'变形：Escape System与共享伤口状态',terrain:[],overrides:[{name:'双重弹药测试射手',bs:14},{name:'逃逸系统模型',s:7,type:'TAG',attribute:'STR',hp:3,maxhp:3,arm:0,states:['immB','stunned'],transmutation:{threshold:2,escape:true,profiles:[{s:7,type:'TAG',attribute:'STR'},{s:2,type:'LI',attribute:'VITA'}]}}],modeId:'DA',instructions:'待机→目标放弃→DA射击，两个20过保失败；形态替换后剩1/3，保留IMM-B/眩晕，中心出现Eclipse。',dice:[8,20,20]};
LESSONS.hatching76={...LESSONS.transAuto76,title:'孵化：首项移动使用成熟形态',terrain:[],overrides:[{name:'种胚教学',s:0,mov:0,states:['seedEmbryo'],transmutation:{type:'hatching',profiles:[{s:0,mov:0},{s:2,mov:4,ph:13}]}},{}],instructions:'开始Move→必须孵化→确认替换→成熟形态MOV4进行移动；没有额外命令消耗。'};

LESSONS.transWipARO76={...LESSONS.symbioBomb75,title:'变形WIP：ARO前成功，状态阶段还原',terrain:[],overrides:[{name:'主动教学',wip:13},{name:'WIP变形反应者',wip:13,transmutation:{type:'wip',mod:-3,profiles:[{s:2,bs:10},{s:2,bs:15}]}}],instructions:'待机→反应者先WIP−3变形（骰8成功）→确认同底盘替换→BS射击B1，使用新BS15。完成命令后结束回合，状态阶段强制恢复BS10。',dice:[8,9,1]};
LESSONS.transWipFail76={...LESSONS.transAuto76,title:'变形WIP：失败重试必须等待下次激活',terrain:[],overrides:[{name:'WIP变形教学',wip:13,transmutation:{type:'wip',mod:-3,profiles:[{s:2,bs:10},{s:2,bs:15}]}},{}],instructions:'先尝试变形骰20失败；同次激活按钮禁用。执行待机＋待机结束后，下一次激活才可再次尝试。',dice:[20]};

LESSONS.proxyARO77={title:'G:Jumper：单一供令与主动代理体ARO',kind:'N5.3 · p94',source:'https://infinitythewiki.com/G:_Jumper',reviewDate:'2026-10-23',question:'多个代理体都能射击ARO吗？',answer:'每条命令只能选一个主动代理体正常反应，其他只能Dodge或Reset。整组只贡献一个命令，状态与生命分别记录。',positions:[[20,28],[19,24]],terrain:[],overrides:[{name:'入侵教学',hp:3,maxhp:3,courage:true},{name:'Proxy Mk2教学',proxyGroup:'posthuman',proxyActive:false,bs:13,lieutenant:true}],extras:[{id:'proxy5',team:1,x:23,y:24,name:'Proxy Mk5教学',proxyGroup:'posthuman',proxyActive:true,lieutenant:false,facing:90,loadout:['combi','cc'],weapon:'combi',ph:13}],instructions:'红方待机→选择Mk2主动代理体，Mk2射击，Mk5只能闪避/Reset；红方待机。普通射击骰8、闪避10，过保1；Mk5闪避移动。命令后转蓝方，整组只生成1正规命令。',dice:[8,10,1]};
LESSONS.proxyActive77={...LESSONS.proxyARO77,title:'G:Jumper：主动轮在代理体之间切换',positions:[[19,28],[35,10]],overrides:[{name:'Proxy Mk2教学',proxyGroup:'posthuman',proxyActive:false,hp:1,maxhp:1},{name:'敌方教学'}],extras:[{id:'proxy5',team:0,x:23,y:28,name:'Proxy Mk5教学',proxyGroup:'posthuman',proxyActive:true,lieutenant:false,facing:-90,loadout:['combi','cc'],weapon:'combi'}],instructions:'用Mk2完成一令，再点击Mk5发起下一令。主动标记随选择切换，两模型的状态及弹药独立；一组只供1正规命令。'};
LESSONS.proxyLost77={...LESSONS.proxyARO77,title:'G:Jumper：当前代理体昏迷后转移标记',overrides:[{name:'攻击教学',bs:14},{name:'Proxy Mk2教学',proxyGroup:'posthuman',proxyActive:true}],extras:[{id:'proxy5',team:1,x:35,y:8,name:'Proxy Mk5教学',proxyGroup:'posthuman',proxyActive:false,lieutenant:false,facing:90,loadout:['combi'],weapon:'combi'}],equipment:{a0:{loadout:['lab'],weapon:'lab'},b0:{loadout:['combi'],weapon:'combi'}},weapon:'lab',modeId:'N',instructions:'Mk2放弃ARO，主动方射击N骰8/过保20失败，Mk2昏迷。命令末选择Mk5，标记转移；切换蓝方依然只有一个正规命令。',dice:[8,20]};
LESSONS.hatchingARO76={...LESSONS.hatching76,title:'孵化：成功Dodge ARO后再应用成熟形态',positions:[[20,28],[20,24]],overrides:[{name:'主动教学'},{name:'种胚反应者',s:0,ph:10,mov:0,states:['seedEmbryo'],transmutation:{type:'hatching',profiles:[{s:0,mov:0,ph:10},{s:2,mov:4,ph:13}]}}],instructions:'主动待机→种胚闪避→主动待机；骰8对种胚PH10成功，先变形再移动。移动阶段成熟S2，PH13，2寸范围。',dice:[8]};
LESSONS.transDeploy76={...LESSONS.symbioAssign74,title:'Auto：部署阶段选择形态',overrides:[{name:'自动变形部署',transmutation:{type:'auto',profiles:[{s:2,mov:4},{s:6,mov:6}]}},{}],extras:[],instructions:'部署界面直接切换Auto形态；仍受任务部署区、完整底盘、地形及单位占位校验。'};

LESSONS.enemyRepeater78={title:'黑客：敌方中继器路径与防火墙选择',kind:'N5.3 · p56–57',source:'https://infinitythewiki.com/Repeater',reviewDate:'2026-10-23',question:'能借敌方中继器攻击谁？',answer:'本人在其ZoC，可攻击其军队任何黑客，应用Firewall−3；多来源防火墙不叠加，由受益者选择。',positions:[[12,28],[36,20]],terrain:[{x:22,y:0,w:1,h:48,height:9,name:'隔断',kind:'wall'}],overrides:[{name:'主动HD教学',hacker:true,hackingDevice:'HD',wip:13,hp:3,maxhp:3,courage:true},{name:'远端敌方黑客',hacker:true,hackingDevice:'HD',wip:13,hackingFirewall:-6,bts:3,hp:3,maxhp:3,courage:true}],extras:[{id:'enemy-relay',name:'敌方中继器',team:1,x:14,y:28,s:0,isDeployable:true,noOrders:true,repeater:true,hp:1,maxhp:1,states:[],noARO:true,loadout:[]}],instructions:'主动待机→远方黑客因敌方中继范围获得ARO→Reset→主动Spotlight选择敌方中继器。结算可选−3或−6，不叠加；−3时SV10、B2骰8/9，Reset20，BTS3/2=2＋PS5＋防火墙3=SV10。',dice:[8,9,20,20,1]};
LESSONS.enemyRepeaterARO78={...LESSONS.enemyRepeater78,title:'黑客：敌方中继器提供远端ARO',extras:[{id:'enemy-relay',name:'红方中继器',team:0,x:34,y:20,s:0,isDeployable:true,noOrders:true,repeater:true,hp:1,maxhp:1,states:[],noARO:true,loadout:[]}],instructions:'主动待机→远方蓝黑客选红方中继器并Spotlight ARO→主动Reset。蓝方WIP13−3=10，主动受防火墙保护。',dice:[20,8,20]};

LESSONS.boost79={title:'Boost：绕墙追击与普通闪避',kind:'N5.3 · p69',source:'https://infinitythewiki.com/Perimeter_Weapons',reviewDate:'2026-10-23',question:'外围武器可以穿墙命中吗？',answer:'需要完整轮廓可通行的路径；不会触发迷彩/伪装/Aerial/其他部署物。只能以普通Dodge避开；无模板误伤友军。',positions:[[20,28],[35,8]],terrain:[{id:'boost-wall',x:18,y:24,w:4,h:.3,height:4,name:'有限高墙',kind:'wall'}],overrides:[{name:'Boost目标',ph:13,hp:3,maxhp:3,courage:true},{name:'敌方教学'}],extras:[{id:'koala79',name:'CrazyKoala',team:1,x:20,y:21,s:1,isDeployable:true,deployableKind:'crazyKoala',noARO:true,noOrders:true,hp:1,maxhp:1,states:[],loadout:[]}],instructions:'主动待机触发隔墙Koala，地图显示绕行轨迹；对方放弃，主动Dodge。PH13−3=10，骰8避开，无过保；Koala移除，进入2寸闪避。',dice:[8]};
LESSONS.boostFail79={...LESSONS.boost79,title:'Boost：闪避失败后的Shock过保',instructions:'Dodge骰20失败，Koala自动命中，PS5/ARM1 SV6过保20失败受1伤；装置移除。',dice:[20,20]};
