LESSONS.friendlyFire80={title:'射入多人近战：逐失败骰选择误伤友军',kind:'N5.3 · p52',source:'https://infinitythewiki.com/Ballistic_Skills',reviewDate:'2026-10-23',question:'射击失败只浪费子弹吗？',answer:'每名交战友军使射击−6；失败骰命中友军，由友军玩家逐颗分配。取消的成功骰不产生误伤。',positions:[[20,28],[20,24]],terrain:[],overrides:[{name:'射入近战教学',bs:14},{name:'被围攻目标',hp:3,maxhp:3,courage:true}],extras:[{id:'friend1',name:'近战友军甲',team:0,x:19.016,y:24,hp:3,maxhp:3,courage:true},{id:'friend2',name:'近战友军乙',team:0,x:20.984,y:24,hp:3,maxhp:3,courage:true}],equipment:{a0:{loadout:['combi'],weapon:'combi'},b0:{loadout:['cc'],weapon:'cc'}},instructions:'主动待机→目标放弃→Combi B3。BS14＋3−12=SV5，骰3/8/20。3命中敌人；8/20失败，分别分配给友军甲乙。三模型各过保一次，20/1/20。',dice:[3,8,20,20,1,20]};

LESSONS.impMulti81={title:'伪装：两次发现只降低一层，延后失效',kind:'N5.3 · p167 Example 2',source:'https://infinitythewiki.com/Impersonation_State',reviewDate:'2026-10-23',question:'两个成功发现会直接揭露IMP-1吗？',answer:'不会；所有ARO同时执行，IMP-1仅变成IMP-2。延后者在主动方未揭露时失去ARO。',positions:[[20,28],[19,24]],terrain:[],overrides:[{name:'IMP-1教学',impersonation:1,states:['impersonation1']},{name:'发现者甲',wip:13}],extras:[{id:'imp-observer',name:'发现者乙',team:1,x:21,y:24,wip:13,facing:90},{id:'imp-delay',name:'延后者',team:1,x:24,y:24,facing:135}],instructions:'主动待机→甲乙发现，第三人延后→主动第二次待机。发现8/9成功，只变IMP-2，第三人无反应。下一令再次发现可揭露，并由拥有者选择朝向。',dice:[8,9]};
LESSONS.impBio81={...LESSONS.impMulti81,title:'生物识别目镜：一次发现揭露IMP-1',extras:[],overrides:[{name:'IMP-1教学',impersonation:1,states:['impersonation1']},{name:'生物识别观察员',wip:13,biometricVisor:true}],instructions:'待机→生物识别发现ARO，WIP13+距离3=16→待机→骰8成功直接揭露IMP-1，选择朝向。'};
LESSONS.impHidden81={...LESSONS.impMulti81,title:'重新伪装：隐匿部署揭露后干扰执行',first:'reimp',extras:[],overrides:[{name:'重新伪装教学',impersonation:1,hp:3,maxhp:3,courage:true},{name:'隐匿射手',hiddenDeployment:true,states:['hiddenDeployment'],bs:12}],instructions:'主动方可宣告重新伪装整令；隐匿射手宣告步枪ARO并揭露，普通BS检定8，过保1成功。命令结束仍为模型，不能恢复IMP。',dice:[8,1]};
LESSONS.impRegain81={...LESSONS.impHidden81,title:'重新伪装：成功恢复IMP-1',terrain:[{id:'imp-wall',x:18,y:25,w:5,h:.4,height:4,name:'视线隔墙'}],overrides:[{name:'重新伪装教学',impersonation:1},{name:'墙后敌人'}],instructions:'主动整令重新伪装→敌人放弃→结束，恢复IMP-1；不是第二短技能或ARO。'};
LESSONS.impDeploy81={...LESSONS.symbioAssign74,title:'伪装部署：敌部署区WIP失败回桌边',overrides:[{name:'伪装部署教学',impersonation:1,wip:13},{name:'敌方教学'}],extras:[],positions:[[20,10],[35,5]],instructions:'勾选进入敌部署区，选择IMP-1部署→锁定WIP检定，骰20失败；恢复模型并回己方桌边，所有关联部署物移除。',dice:[20]};
LESSONS.supportSequence82={title:'支援程序：仙尘被另一黑客的强化反应取消',kind:'N5.3 · p60',source:'https://infinitythewiki.com/Supportware',question:'给一个REM新支援，其他REM的仙尘会保留吗？',answer:'不会：整个旧支援程序取消。辅助/强化/仙尘只限主动整令；新程序宣告即取消被替代支援。',positions:[[20,28],[20,20]],terrain:[],overrides:[{name:'EVO甲',hackingDevice:'EVO',type:'REM'},{name:'远处敌人',hp:3,maxhp:3,courage:true}],extras:[{id:'evo2',team:0,x:24,y:28,name:'EVO乙',hackingDevice:'EVO',type:'REM'},{id:'rem82',team:0,x:24,y:24,name:'前沿REM',hackingDevice:null,type:'REM',loadout:['combi'],weapon:'combi',hp:3,maxhp:3,courage:true}],first:'program:fairyDust',instructions:'EVO甲整令仙尘选择REM；随后EVO乙整令强化反应指定前沿REM。观察仙尘全军消失；结束回合，敌人待机，前沿REM射击ARO有2骰。',dice:[8,9,1,1]};
LESSONS.proxyTransfer82={...LESSONS.proxyActive77,title:'G:Jumper：战术阶段整体转战斗组',tacticalWindow:true,extras:[{...LESSONS.proxyActive77.extras[0],combatGroup:1},{id:'group2',team:0,x:28,y:28,name:'G2普通部队',combatGroup:2,proxyGroup:null,proxyActive:false,lieutenant:false}],overrides:[{...LESSONS.proxyActive77.overrides[0],combatGroup:1},{}],instructions:'战术阶段选择G2并转组；两个代理体同时变G2，只消耗1指挥令，G1正规1→0，G2正规1→2。开始命令后不可再转组。'};
LESSONS.proxyJump82={...LESSONS.proxyARO77,title:'G:Jumper：敌战斗空降后双代理体分别反应',overrides:[{name:'空降教学',combatJump:true,ph:13,offTable:true,airborneOrderAvailable:true,hp:3,maxhp:3,courage:true},{name:'Proxy Mk2教学',proxyGroup:'posthuman',proxyActive:false,bs:13,lieutenant:true,facing:90}],extras:[{...LESSONS.proxyARO77.extras[0],offTable:false,combatJump:false,airborneOrderAvailable:false,x:23,y:24,facing:-90}],instructions:'空降至(20,28)，PH8成功。Mk2成为主动代理体射击；背对落点的Mk5只能闪避（PH13−3=10）。射击9与闪避8均普通成功，敌人过保1；Mk5闪避移动。',dice:[8,9,8,1]};
LESSONS.discoverSplit83={title:'发现后分枪：失败只取消标记的那组B',kind:'N5.3 · p78 / p36',source:'https://infinitythewiki.com/Discover',question:'主目标发现失败，另一目标也不能射击吗？',answer:'只取消仍未被发现的标记所分配的B；其他目标的独立骰池照常执行，未使用的B不能重新分配。',positions:[[20,28],[19,24]],terrain:[],overrides:[{name:'发现分枪教学',bs:14,wip:13},{name:'迷彩目标',camouflage:true,states:['camouflaged']}],extras:[{id:'split83',team:1,x:23,y:24,facing:90,name:'已显露目标',hp:3,maxhp:3,courage:true,camouflage:false,bs:11}],equipment:{a0:{loadout:['hmg'],weapon:'hmg'},b0:{loadout:['combi'],weapon:'combi'}},first:'discover',instructions:'首项发现迷彩b0；迷彩放弃，另一目标复合步枪ARO。第二项HMG B4分2+2，先选迷彩。发现20失败；仅显露目标掷8/9对ARO6，产生2命中和2次过保20/1。',dice:[20,8,9,6,20,1]};
