LESSONS.holoDelay84={...LESSONS.holoMove84,title:'全息回声：延后只能反应真实持有者',route:null,instructions:'待机，蓝方选择回声甲后延后；主动射击蓝方，揭露真实持有者。蓝方目标锁为真实持有者，再步枪ARO。8/9/20对6，主动2命中；假体命令结束才全部消失。',dice:[8,9,20,6,1,1],overrides:[{name:'全息持有者',holoprojector:true,states:['holoecho'],bs:12,hp:3,maxhp:3,courage:true},{name:'回声观察者',bs:12,hp:3,maxhp:3,courage:true}]};
