LESSONS.holoReturn84={...LESSONS.holoMove84,title:'全息回声：主动整令重新投影',extras:[],overrides:[{name:'全息持有者',holoprojector:true},{name:'隔墙观察者'}],positions:[[20,28],[20,24]],terrain:[{x:18,y:25,w:4,h:.3,height:4,name:'投影视线墙'}],first:'reholo',route:null,instructions:'首项选择重新全息回声整令；蓝方放弃，结算后点击模型左右选择新回声方向，确认生成。新回声必须接触真实模型，不能在远处凭空生成。',dice:[1]};
LESSONS.holoDeploy84={...LESSONS.holoReturn84,title:'全息回声：部署一致性与状态阶段恢复',terrain:[],positions:[[20,40],[35,5]],pregame:{stage:'deploy',firstDeployment:0,step:0,reserves:{0:[],1:[]},sides:{0:'south',1:'north'}},editableDeploy:true,first:'move',instructions:'部署时点放置全息回声，在(24,40)、(28,40)部署并确认；验证同部署区及8寸链式一致性。测量后这组位置固定。'};

LESSONS.modelLos85={title:'模型遮挡：S7挡住S2射击线',kind:'N5.3 · p19',source:'https://infinitythewiki.com/Line_of_Fire',question:'友军也会遮挡视线吗？',answer:'模型轮廓会遮挡；标记不挡。宣告移动技能的模型在本命令路线上不挡视线。单位本身不提供部分掩体。',terrain:[],positions:[[20,28],[20,20]],overrides:[{name:'后方射手',bs:12},{name:'被遮挡目标',hp:3,maxhp:3,courage:true}],extras:[{id:'los-block85',name:'遮挡S7模型',team:0,x:20,y:24,s:7,type:'TAG',hp:3,maxhp:3,loadout:['combi'],weapon:'combi',facing:-90}],first:'idle',instructions:'保持S7静止，后方射手待机时无敌方射击ARO，射击目标按钮被视线阻止。取消后改Move，红方横移到(22,28)，才可正常射击目标；模型不产生掩体加成。',dice:[8,9,20,1,1]};
LESSONS.markerLos85={...LESSONS.modelLos85,title:'标记不挡视线：迷彩与假体例外',extras:[{...LESSONS.modelLos85.extras[0],name:'S7迷彩教具',states:['camouflaged'],camouflage:true}],instructions:'中间模型变CAMO标记；后方待机仍产生步枪ARO。蓝方放弃后红方射击，8/9/20两命中，ARM1+PS7=8，没有模型提供的掩体。'};
LESSONS.movingLos85={...LESSONS.modelLos85,title:'移动模型不挡：协调同令路线可穿透视线',extras:[{...LESSONS.modelLos85.extras[0],name:'协调S7'}],instructions:'手工将后方射手与S7编入协调命令，选择Move，两者原地Move 0寸。S7本令宣告移动，因此后方射手能射击蓝方；S7本身可按协调规则同技能攻击。'};

LESSONS.halfBridge86={title:'高架窄桥：半底盘通过，完整底盘停靠',kind:'N5.3 · p29',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/Move',question:'桥宽只有12.5mm，25mm底盘能走过去吗？',answer:'可以经过，途中至少半底盘支撑；本段Move必须结束在完整底盘能支撑的位置，不能在窄桥上结束再等下一段。',positions:[[20.5,24,4],[35,10]],terrain:[{x:18,y:22,w:3,h:4,height:4,kind:'building',name:'起点平台'},{x:21,y:24-25/101.6,w:2,h:25/50.8,bottom:3.7,height:4,kind:'building',name:'12.5mm窄桥'},{x:23,y:22,w:3,h:4,height:4,kind:'building',name:'终点平台'}],instructions:'开始Move→点(22,24)窄桥，尝试确认被完整底盘校验阻止；继续点(23.5,24)终点平台，可确认3寸移动并完成Idle。',dice:[1]};
LESSONS.steps86={title:'连续台阶：逐级翻越而非累计高度限制',kind:'N5.3 · p30',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/General_Movement_Rules',question:'S2能用Move走上累计3.6寸台阶吗？',answer:'每一级高度差不超过轮廓高度，且级间有至少半底盘宽的支撑面时可以。翻越的竖直距离不扣MOV，完整路线仍要记入ARO。',positions:[[19.5,24],[35,10]],terrain:[{x:20,y:22,w:.6,h:4,height:1.2,kind:'building',name:'台阶1'},{x:20.6,y:22,w:.6,h:4,height:2.4,kind:'building',name:'台阶2'},{x:21.2,y:22,w:4,h:4,height:3.6,kind:'building',name:'台阶3'}],instructions:'开始Move→点击(22.5,24)平台，横向3寸、脚底升到3.6寸；确认→对方放弃→第二项Move原路返回，脚底回到0寸。',dice:[1]};
LESSONS.thinSteps86={...LESSONS.steps86,title:'连续台阶：不足半底盘的中间台阶不能借力',terrain:[{x:20,y:22,w:.3,h:4,height:1.2,kind:'building',name:'过窄台阶1'},{x:20.3,y:22,w:.3,h:4,height:2.4,kind:'building',name:'过窄台阶2'},{x:20.6,y:22,w:4,h:4,height:3.6,kind:'building',name:'高台'}],instructions:'开始Move点击高台；系统只规划到可到达的边缘，不能无条件爬升3.6寸。要上高台必须Jump/Climb并满足各自要求。'};
LESSONS.roofPeek86={title:'屋边探出：半底盘看楼下，再退回完整支撑',kind:'N5.3 · p31',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/General_Movement_Rules',question:'能暂时探出屋边射击，再退回屋顶吗？',answer:'途中可以半底盘悬出；不能在该点结束。反应与主动射击可选途中点，地形护栏仍要计算。',positions:[[21.2,22,4],[19.4,22]],terrain:[{x:20,y:20,w:4,h:4,height:4,kind:'building',name:'屋边探出'}],overrides:[{name:'屋顶射手',facing:180,bs:12},{name:'墙脚目标',facing:0,hp:3,maxhp:3,courage:true}],instructions:'Move至(20,22)半底盘探出，确认应被阻止；退回(21.2,22)再确认。蓝方有途中射击ARO；主动可在途中点开火，最终位置仍在屋顶。',dice:[8,9,20,1,1]};

LESSONS.climbDown87={title:'攀爬示例2：9寸墙分两令下攀',kind:'N5.3 · p33 Example 2',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/Climb',question:'6寸攀爬能一次下9寸墙吗？',answer:'不能，先攀爬至墙中段，下一条命令继续。墙面不是地面，普通模型此时不能宣告其他技能或ARO。',positions:[[20+25/50.8,24,9],[40,10]],terrain:[{id:'cliff87',x:20,y:22,w:4,h:4,height:9,kind:'building',name:'9寸峭壁'}],first:'climb',instructions:'点击楼外(19,24)规划下降，第一条命令结束脚底约Z3.98并挂墙；第二条Climb继续同方向到地面，两个整令均无第二项技能。',dice:[1]};
LESSONS.climbLanding87={...LESSONS.climbDown87,title:'攀爬：遇到较低水平平台立即落地',terrain:[...LESSONS.climbDown87.terrain,{id:'ledge87',x:18,y:22,w:2,h:4,height:5,kind:'building',name:'5寸平台'}],instructions:'同一9寸楼左侧有5寸平台；向下Climb只下降到5寸完整支撑面即停止，不能穿过平台继续下到地面。'};
LESSONS.jumpObstacle87={title:'跳跃示例1：越过1.75寸障碍',kind:'N5.3 · p34 Example 1',reviewDate:'2026-10-23',source:'https://infinitythewiki.com/Jump',question:'比S2高的1.75寸墙能直接Move吗？',answer:'需要Jump或Climb。普通Jump整令为MOV1+2，轨迹按三维折线，不能改变水平前进方向，需完整水平落点。',positions:[[19.5,24],[35,10]],terrain:[{id:'jumpwall87',x:20,y:22,w:.2,h:4,height:1.75,kind:'wall',name:'1.75寸高墙'}],first:'jump',instructions:'点击墙后(21,24)落点；自动折线绕过实体，约5寸，可确认整令；不能继续第二项Move。',dice:[1]};
LESSONS.jumpTooHigh87={...LESSONS.climbDown87,title:'跳跃示例2：10寸高处不能免费坠落',kind:'N5.3 · p34 Example 2',source:'https://infinitythewiki.com/Jump',positions:[[20+25/50.8,24,10],[40,10]],terrain:[{id:'drop87',x:20,y:22,w:4,h:4,height:10,kind:'building',name:'10寸楼'}],first:'jump',instructions:'点击地面(19,24)，需要大于6寸，拒绝路线；点击跳过移动按整令Idle完成，不坠落，不出现第二项技能。'};
LESSONS.jumpRoof87={...LESSONS.halfBridge86,title:'跳跃示例3：跨屋顶与完整落点',kind:'N5.3 · p35 Example 3',source:'https://infinitythewiki.com/Jump',terrain:[{id:'jumpstart87',x:18,y:22,w:3,h:4,height:4,kind:'building',name:'起跳楼'},{id:'jumpend87',x:23,y:22,w:3,h:4,height:4,kind:'building',name:'目标楼'}],first:'jump',instructions:'点击目标楼边缘(23.1,24)不能容纳完整底盘；改(23.5,24)，3寸平跳可落地，无第二项行动。'};
LESSONS.jumpVertical87={...LESSONS.jumpObstacle87,title:'跳跃示例4：原地垂直跳与禁止空中折返',terrain:[],positions:[[20,28],[35,10]],instructions:'普通Jump设置空中高度3，点垂直升降；随后点击原起点落地，合计6寸可执行。另重置：指定向右1寸、Z1空中点，再企图回原点，应拒绝改变水平前进方向。'};

LESSONS.jumpLanding88={...LESSONS.jumpObstacle87,title:'跳跃落地：屋顶接触即结束，不能当作空中点',positions:[[19.5,24],[35,10]],terrain:[{id:'jump-roof88',x:20,y:22,w:4,h:4,height:4,kind:'building',name:'4寸楼'}],instructions:'开始Jump，空中高度4，地图用途空中途经点，点击屋顶(21,24)应拒绝接触表面；改最终落点可落地，普通Jump整令没有第二项Move。'};
LESSONS.motorcycle88={...LESSONS.jumpVertical87,title:'摩托限制：不能攀爬或向上跳跃',overrides:[{name:'骑乘摩托教学',motorcycle:true,mov:4},{name:'观察者'}],instructions:'骑乘时首项列表没有Climb/谨慎移动；Jump高度1的空中点被拒绝。平跳仍可执行整令。',question:'骑乘摩托可以攀爬或向上跳吗？',answer:'不可以；平跳或向下跳仍需符合距离、完整落点和普通跳跃方向限制。此教学单独验证骑乘限制，不模拟上下车。'};

LESSONS.supportIsolated89={title:'支援失效：EVO孤立后取消强化反应',kind:'N5.3 · p60',source:'https://infinitythewiki.com/Supportware',question:'维持者孤立后，遥控机还能保持B2 ARO吗？',answer:'不能。维持者进入Isolated或Null时程序自动取消；修复维持者也不会自动恢复旧程序。',terrain:[],positions:[[20,28],[20,22]],overrides:[{name:'攻击黑客',hackingDevice:'HD',hacker:true,hp:3,maxhp:3,courage:true},{name:'蓝方EVO',hackingDevice:'EVO',hacker:true,type:'REM',attribute:'STR',bts:0,supportware:{id:'enhancedReaction',targetId:'rem89',team:1},courage:true}],extras:[{id:'rem89',name:'受支援REM',hackingDevice:null,hacker:false,team:1,x:24,y:22,facing:90,type:'REM',hp:3,maxhp:3,courage:true,bs:12,loadout:['combi'],weapon:'combi'}],first:'idle',instructions:'首令待机，蓝方均放弃；Oblivion攻击蓝方EVO，骰8/20命中1次，BTS20失败孤立。次令待机，受支援REM射击ARO应仅1骰，旧强化反应不再有效。',dice:[8,20,20,8,1]};
LESSONS.supportNull89={...LESSONS.supportIsolated89,title:'支援失效：EVO昏迷后取消强化反应',overrides:[{name:'主动射手',bs:12,hp:3,maxhp:3,courage:true},{name:'蓝方EVO',hackingDevice:'EVO',hacker:true,type:'REM',attribute:'STR',arm:0,bts:0,supportware:{id:'enhancedReaction',targetId:'rem89',team:1}}],instructions:'首令待机，蓝方均放弃；步枪射击EVO，8/20/20命中一次，ARM20失败昏迷。次令待机，受支援REM只射1骰；维持者不再提供ARO。',dice:[8,20,20,20,8,1]};
LESSONS.wildParrot89={title:'WildParrot：外围部署后按E/M地雷结算',kind:'N5.3 · p69/83',source:'https://infinitythewiki.com/WildParrot',question:'WildParrot会像Koala追到目标身边吗？',answer:'不会。它在本人控制区内按外围规则放置，命令结束后成为明置的E/M地雷；触发用小泪滴，BTS减半两次过保，失败使HI/REM/TAG孤立且IMM-B。',terrain:[],positions:[[20,28],[20,20]],overrides:[{name:'WildParrot携带者',deployableItems:['wildParrot']},{name:'HI测试目标',type:'HI',bts:3,hp:2,maxhp:2,courage:true}],first:'idle',instructions:'待机→放置WildParrot至(20,23)，蓝方放弃。命令末出现明置S1模型，弹药0/1。结束红回合，HI待机，红方放弃；HI闪避20失败，两次BTS过保20/1。无伤口，获得孤立和IMM-B，装置移除。',dice:[20,20,1]};

LESSONS.deployOccupied90={title:'部署FAQ：闪避占位后重新选择合法位置',kind:'N5.3 · Place Deployable FAQ',source:'https://infinitythewiki.com/Place_Deployable',question:'宣告的位置被敌人闪避占住了怎么办？',answer:'命令结束时可改到另一合法位置；如果无法合法放置，部署物损失，使用次数不返还。',terrain:[],positions:[[20,28],[23,28]],overrides:[{name:'中继器携带者',deployableItems:['deployableRepeater'],facing:0},{name:'占位闪避者',facing:180}],first:'idle',instructions:'待机，敌方Dodge ARO；第二项放中继器到(20.99,28)。Dodge8成功，敌人向左移动约2寸到(21.02,28)占位；结算末改放本人上方(20,27.01)，无需重掷/重付弹药。',dice:[8]};
LESSONS.deployLost90={...LESSONS.deployOccupied90,title:'部署FAQ：唯一出口被占，无合法位置则损失',terrain:[{id:'c90l',x:18.5,y:26,w:1,h:4,height:4,name:'厚左墙'},{id:'c90t',x:19.5,y:26,w:4,h:1.35,height:4,name:'上墙'},{id:'c90b',x:19.5,y:28.65,w:4,h:1.35,height:4,name:'下墙'}],instructions:'同样把中继器宣告到(20.99,28)，敌方Dodge进入(21.02,28)；狭窄槽内唯一相邻空位被占，其他位置穿墙/无法接触。选择无法合法放置而损失，弹药仍消耗1。'};
const mine90={id:'mine90',name:'蓝方休克地雷',team:1,x:20,y:24,s:2,actualSilhouette:0,states:['camouflaged'],isDeployable:true,deployableKind:'shockMine',noOrders:true,noARO:true,hp:1,maxhp:1,loadout:[],weapon:'cc'};
LESSONS.mineCamo90={title:'地雷：迷彩待机不触发，攻击揭露后触发',kind:'N5.3 · Mines',source:'https://infinitythewiki.com/Mines',question:'迷彩进入地雷范围一定触发吗？',answer:'迷彩标记不触发；宣告攻击解除迷彩后，作为敌方模型触发。模板仍不能覆盖地雷友军。',terrain:[],positions:[[20,28],[20,18]],overrides:[{name:'迷彩射手',camouflage:true,states:['camouflaged'],hp:2,maxhp:2,courage:true},{name:'远方射手',hp:3,maxhp:3,courage:true}],extras:[mine90],first:'idle',instructions:'先Idle+Idle，敌方延后后失效，雷保持。再Idle，敌方延后，主动步枪攻击揭露，敌方放弃；主动8/20/20一命中，目标保1成功；自己中雷保20失败，失1伤但雷移除。',dice:[8,20,20,1,20]};
LESSONS.mineFriendly90={...LESSONS.mineCamo90,title:'地雷：昏迷友军挡住所有合法模板',overrides:[{name:'红方移动者',hp:2,maxhp:2},{name:'远方射手'}],extras:[mine90,{id:'friend90',name:'昏迷蓝TAG',team:1,x:20,y:26,s:7,type:'TAG',attribute:'STR',hp:0,maxhp:3,states:['unconscious'],noARO:true,loadout:[]}],instructions:'红方Idle+Idle，远方敌人放弃。即使友军已昏迷，任何能命中红方的模板都会覆盖它，地雷不触发、不揭露、不消耗。'};

LESSONS.coordImpact91={title:'圆模板ARO：协调成员分别拼骰，不共享抵消',kind:'N5.3 · Impact Template',source:'https://infinitythewiki.com/Impact_Template_Weapons',question:'先锋赢下导弹，旁边同伴也安全了吗？',answer:'每名被模板波及者分别拼骰；同一导弹骰可以输给先锋、同时击中另一成员。只生成一次导弹反应骰。',terrain:[],positions:[[20,28],[20,16]],overrides:[{name:'协调先锋',bs:12,hp:5,maxhp:5,courage:true},{name:'导弹反应者',bs:11,hp:5,maxhp:5,courage:true}],extras:[{id:'wing91',name:'协调成员',team:0,x:22,y:28,bs:12,hp:5,maxhp:5,courage:true,facing:-90,loadout:['combi'],weapon:'combi'}],equipment:{a0:{loadout:['combi'],weapon:'combi'},b0:{loadout:['missile'],weapon:'missile'}},first:'idle',instructions:'勾选先锋与成员协调激活；Idle，导弹对先锋宣告圆形模板ARO。主动两人步枪射击：先锋9/20、成员7，导弹8。先锋赢/成员输，导弹只令成员3次EXP过保，反应者承受先锋1次命中。',dice:[9,20,7,8,1,1,1,1]};
LESSONS.coordImpactCrit91={...LESSONS.coordImpact91,title:'圆模板ARO：暴击只对主目标有效',instructions:'同样协调Idle→导弹圆模板→两人步枪；先锋8/20，成员12，导弹11正好SV暴击。先锋承受EXP3+暴击1=4次过保；成员以12胜过作为普通成功的11，不受伤，导弹反应者承受1次命中。',dice:[8,20,12,11,1,1,1,1,1]};
LESSONS.coordImpactDodge91={...LESSONS.coordImpact91,title:'圆模板ARO：主副目标分别闪避',overrides:[{...LESSONS.coordImpact91.overrides[0],ph:13},{...LESSONS.coordImpact91.overrides[1]}],extras:[{...LESSONS.coordImpact91.extras[0],ph:13}],instructions:'协调Idle→导弹对先锋圆模板→主动闪避。先锋12/SV13输给主目标暴击11；成员12/SV13击败作为普通成功的11。先锋4次过保，成员获得闪避移动，分别结算。',dice:[12,12,11,1,1,1,1]};

LESSONS.impactBlind92={...LESSONS.coordImpact91,title:'主动闪避圆模板：背向时PH−3',overrides:[{...LESSONS.coordImpact91.overrides[0],name:'背向闪避者',facing:90,ph:13},{...LESSONS.coordImpact91.overrides[1]}],extras:[],instructions:'无需协调，Idle→导弹圆模板ARO→闪避。背向无LoF，PH13−3=10，骰12失败；导弹8成功，3次EXP过保，无闪避移动。',dice:[12,8,1,1,1]};
LESSONS.impactLinkedBlind92={...LESSONS.coordImpactDodge91,title:'协调闪避：副目标背向时独立PH−3',extras:[{...LESSONS.coordImpact91.extras[0],ph:13,facing:90}],instructions:'协调两人Idle→导弹对先锋圆模板→闪避。先锋12/SV13胜导弹8；背向成员12/SV10失败，承担3次EXP过保。仅先锋可以移动。',dice:[12,12,8,1,1,1]};

