LESSONS.discoBallerOccupied93={...LESSONS.deployOccupied90,equipment:{a0:{loadout:['combi','discoBaller'],weapon:'combi'}},title:'射击部署FAQ：Disco Baller被闪避占位后改放',overrides:[{name:'Disco Baller携带者',facing:0,deployableItems:[],loadout:['combi','discoBaller']},{name:'占位闪避者',facing:180}],instructions:'Idle→敌Dodge→投掷／发射Disco Baller至(21.3,28)；两方骰8普通成功。敌向左闪避到(21.1,28)占位；命令末重新选择(20.1,26.8)，不重新检定、不重复消费。',dice:[8,8]};

LESSONS.protheionIncoming94={...LESSONS.protheionHeal72,title:'Protheion：先获得两点VITA，再承受同令枪伤',overrides:[{name:'未伤吸取者',cc:20,hp:2,maxhp:2,protheion:true,courage:true},{name:'双伤近战目标',cc:15,hp:2,maxhp:2,arm:0}],extras:[{id:'gun94',name:'旁侧射手',team:1,x:25,y:25,facing:180,bs:14,protheion:false,loadout:['combi'],weapon:'combi'}],instructions:'Idle→近战目标CC ARO、旁侧射手步枪ARO→主动DA近战。12胜6，旁侧8/SV11普通命中。敌20/20失败两次DA；自身20失败枪保。先Power-Up2至4/4，再受1伤成为3/4，保持Power-Up2。',dice:[12,6,8,20,20,20]};
LESSONS.immBTrinity94={title:'IMM-B：Trinity三发对Reset−3',kind:'N5.3 · p165',source:'https://infinitythewiki.com/Immobilized-B_State',question:'IMM-B可以选择射击或闪避ARO吗？',answer:'只能Reset，WIP−3；面对通讯攻击为面对面。成功解除IMM-B，失败仍保留状态并独立过保。',terrain:[],positions:[[20,28],[20,22]],overrides:[{name:'杀手黑客',hackingDevice:'KHD',hacker:true,wip:13},{name:'被束缚黑客',hackingDevice:'HD',hacker:true,wip:13,bts:0,hp:3,maxhp:3,states:['immB']}],first:'idle',instructions:'Idle→目标唯一可用Reset ARO→主动Trinity。8/9/12对Reset20，三发命中三次BTS过保1/1/1；IMM-B保留，不进入勇气。',dice:[8,9,12,20,1,1,1]};
LESSONS.immBReset94={...LESSONS.immBTrinity94,title:'IMM-B：Reset赢下Trinity并取消状态',instructions:'同样Idle→Reset→Trinity；主动2/3/4，目标Reset9/SV10获胜。无过保，IMM-B取消且可恢复正常行动。',dice:[2,3,4,9]};

LESSONS.engineerEm94={...LESSONS.auditEngineerPara,positions:[[20,30],[24,27]],title:'工程师：先解除IMM-B等状态，再受同令E/M模板',overrides:[{name:'工程师时序训练员',engineer:true,facing:0,hp:2,maxhp:2,courage:true},{name:'E/M模板测试手',facing:135}],equipment:{b0:{loadout:['emTemplate94'],weapon:'emTemplate94',armyWeapons:{emTemplate94:{name:'E/M直射模板（教学）',modes:[{id:'template',name:'电磁 E/M · 大泪滴',kind:'direct',b:1,ps:7,ammo:'EM',template:'large',bands:[]}]}}}},extras:[{id:'para-patient',name:'被束缚重步兵',team:0,x:20+25/25.4,y:30,z:0,type:'HI',hp:2,maxhp:2,bts:0,ph:10,states:['immB','isolated','targeted'],loadout:['combi','cc'],weapon:'combi'}],instructions:'Idle→蓝方E/M模板覆盖两人→工程师解除友军状态。WIP7先清除IMM-B/孤立/被标记；随后双方各2保20/1，工程师孤立，HI重新孤立+IMM-B，但被标记已解除，生命均2/2。',dice:[7,20,1,20,1]};

LESSONS.syncStart95={title:'同步附属：起始超距断连，靠近后命令末恢复',kind:'N5.3 · Peripheral / Coherency',source:'https://infinitythewiki.com/Peripheral',question:'已经断连的附属能自己走回控制范围吗？',answer:'不能。控制者可移动靠近，在合规一致性检查时恢复连接；断连者无命令和ARO。移动途中的距离不提前结算。',terrain:[],positions:[[20,28],[43,43]],overrides:[{name:'同步控制者'},{name:'远方观察员',facing:45}],extras:[{id:'sync95',name:'同步附属',peripheral:'synchronized',controllerId:'a0',team:0,x:31,y:28,facing:-90,noOrders:true,loadout:['combi'],weapon:'combi'}],first:'move',instructions:'控制者开始Move，起始检查附属超距立即断连。控制者向右走约4寸，附属不得移动。第二项Idle，命令结束回到一致性，自动恢复连接。',dice:[8]};
LESSONS.syncEnd95={...LESSONS.syncStart95,title:'同步附属：移动途中保留，命令结束超距断连',extras:[{...LESSONS.syncStart95.extras[0],x:28.5}],instructions:'控制者向左Move约4寸，附属选择Idle；第一段结束仍保持连接。第二项Idle后，结束检查超距断连。下一令控制者向右返回，结束后恢复。'};
LESSONS.servantNull95={...LESSONS.syncStart95,title:'仆从：无距离上限，控制者昏迷才断连',positions:[[20,28],[20,18]],overrides:[{name:'医生控制者',doctor:true},{name:'远方射手',facing:90,bs:11}],extras:[{...LESSONS.syncStart95.extras[0],name:'远处医务仆从',peripheral:'servant',x:35,y:28},{id:'medic95',name:'救援医生',doctor:true,team:0,x:20-25/25.4,y:28,hp:2,maxhp:2,courage:true,loadout:['combi'],weapon:'combi'}],first:'idle',instructions:'控制者Idle→敌步枪ARO→控制者Idle。仆从距离15寸不因超距断连；敌骰8命中、过保20失败控制者昏迷，命令结束仆从断连且不能激活。',dice:[8,20]};

LESSONS.fireteamHack96={title:'火力组：两名黑客的不同程序ARO',kind:'N5.3 · 明确教学设备覆写',source:'https://infinitythewiki.com/Fireteams:_Basic_Rules',question:'同组黑客使用不同程序会脱组吗？',answer:'不会。反应轮每名黑客可以使用不同程序，均算黑客组ARO；主动轮则只有队长执行黑客攻击，其他成员Idle，且没有射击SD奖励。',terrain:[],fireteam:true,armyProfiles:[1560,1561,24,[201,139]],positions:[[20,24],[18,24],[22,24],[20,29]],overrides:[{name:'组长黑客',team:0,hackingDevice:'HD',hackingUpgrades:[],wip:13,hp:3,maxhp:3,facing:90,courage:true},{name:'组员黑客',team:0,hackingDevice:'HD',hackingUpgrades:[],wip:13,hp:3,maxhp:3,facing:90,courage:true},{name:'普通组员',team:0,hackingDevice:null,hackingUpgrades:[],hp:3,maxhp:3,facing:90,courage:true},{name:'蓝方重步兵教学靶',team:1,type:'HI',hackingDevice:null,hackingUpgrades:[],wip:13,hp:3,maxhp:3,bts:0,facing:-90,courage:true}],first:'idle',instructions:'先结束红方回合。蓝方Idle→红组长遗忘、组员碳化、普通组员放弃→蓝方Reset。6失败于10/11，两种程序分别过保，火力组保持3人L3。设备为标明的教学覆写，不修改导入军表。',dice:[6,10,11,20,20,20]};
LESSONS.fireteamHackMinority96={...LESSONS.fireteamHack96,title:'火力组：黑客多数，闪避成员脱组',instructions:'蓝方Idle→两名红方黑客分别遗忘/碳化，普通组员Dodge→确认ARO后普通成员立即脱组，剩余2人L2。蓝方Reset，继续完整结算与闪避移动。',dice:[6,10,11,8,1,1,1]};
LESSONS.fireteamHackActive96={...LESSONS.fireteamHack96,title:'火力组：主动黑客仅队长执行，无射击SD',instructions:'红方组长Idle→蓝方Reset→队长宣告遗忘B2。只有队长2骰，无+1SD；另一个组员黑客Idle。主动10/11对Reset6，两次BTS过保1/1通过，完整结束。',dice:[10,11,6,1,1]};
LESSONS.fireteamCC96={...LESSONS.fireteamHack96,title:'火力组：B3近战对武术L5的B2＋1SD',source:'https://infinitythewiki.com/Fireteam_Examples',question:'武术L5在反应轮有几颗骰？',answer:'武术+1B在双方回合有效。B2加1SD共掷3颗、弃1颗；主动三人接触，只有队长执行CC，两个支援成员使B1变B3。',positions:[[20,25+25/25.4],[20-25/25.4,25],[20+25/25.4,25],[20,25]],overrides:[{name:'近战组长',team:0,cc:20,martialArts:0,hackingDevice:null,hackingUpgrades:[],hp:3,maxhp:3,arm:0,courage:true},{name:'左侧支援',team:0,cc:20,martialArts:0,hackingDevice:null,hackingUpgrades:[],hp:3,maxhp:3,arm:0,courage:true},{name:'右侧支援',team:0,cc:20,martialArts:0,hackingDevice:null,hackingUpgrades:[],hp:3,maxhp:3,arm:0,courage:true},{name:'武术L5教学对手',team:1,s:2,type:'LI',remotePresence:false,cc:20,martialArts:5,hp:3,maxhp:3,arm:0,courage:true}],equipment:Object.fromEntries(['a0','b0','lesson-2','lesson-3'].map(id=>[id,{loadout:['cc'],weapon:'cc',armyWeapons:{}}])),instructions:'红组长Idle→蓝方CC ARO→红组长CC。红B3/SV17，蓝B2+1SD/SV23掷3骰，弃4留10/12，赢2次命中；红方1/1过保通过。支援者不另掷骰。',dice:[7,8,9,4,10,12,1,1]};

LESSONS.infiltrationMine97={...LESSONS.symbioAssign74,pregame:{...LESSONS.symbioAssign74.pregame,firstTurn:0},title:'潜入与布雷者：先摆双迷彩，再PH−3',source:'https://infinitythewiki.com/Infiltration',question:'潜入检定在地雷放下之前还是之后？',answer:'先放模型／标记与部署物并检查控制区，再掷PH−3；失败退回己方桌边，取消部署时的标记／隐匿，已用地雷移除且不退库存。',positions:[[20,20],[35,5]],overrides:[{name:'潜入布雷教学兵',infiltration:true,infiltrationPH:18,infiltrationAttempt:true,camouflage:true,minelayer:1},{name:'敌方模型'}],extras:[],equipment:{a0:{loadout:['combi','cc','shockMine'],weapon:'combi',armyWeapons:{}}},instructions:'选择迷彩部署→布雷者放雷(23,20)，两者均迷彩→PH18−3=15掷12成功。检查模型锁定、地雷仍在、库存2/3。',dice:[12]};
LESSONS.infiltrationMineFail97={...LESSONS.infiltrationMine97,title:'潜入与布雷者：失败失去地雷并回桌边',overrides:[{...LESSONS.infiltrationMine97.overrides[0],camouflageUses:1},{}],instructions:'先迷彩部署，再(23,20)放雷→PH15掷20失败。地雷从地图移除，库存仍2/3；回己方桌边以模型部署，一次性迷彩已用。',dice:[20]};
LESSONS.infiltrationHidden97={...LESSONS.infiltrationMine97,title:'潜入与隐匿布雷：地雷在场，真实位置私下记录',overrides:[{...LESSONS.infiltrationMine97.overrides[0],hiddenDeployment:true},{}],instructions:'选择隐匿部署，布雷者仍能在(23,20)放雷。检定12/SV15成功，本体隐藏而地雷保留；本工具是共享屏幕教学，未提供双方账户隐私。',dice:[12]};
LESSONS.infiltrationReroll97={...LESSONS.infiltrationMine97,title:'潜入重掷：失败后以技能指定PH重掷',overrides:[{...LESSONS.infiltrationMine97.overrides[0],infiltrationPH:10,infiltrationRerollPH:18},{}],instructions:'先迷彩+放雷。首次20/SV7失败，装备和位置保留并锁定；选择重掷后12/SV15成功，地雷保留且仅扣一发。',dice:[20,12]};
LESSONS.infiltrationRerollFail97={...LESSONS.infiltrationReroll97,title:'潜入重掷：第二次失败必须接受',instructions:'首次20失败→重掷仍20失败，不再提供第三次；地雷移除、库存不退，返回己方桌边。',dice:[20,20]};
LESSONS.minelayerEnemy97={...LESSONS.infiltrationMine97,title:'布雷者：敌方迷彩阻止部署地雷',positions:[[20,20],[27,20]],overrides:[{...LESSONS.infiltrationMine97.overrides[0]}, {name:'敌方潜入迷彩',camouflage:true,states:['camouflaged'],infiltration:true}],instructions:'尝试在(23,20)布雷，因触发区有敌方迷彩拒绝；改放(15,20)成功，再完成潜入检定。失败的放置不扣库存。'};
LESSONS.minelayerPerimeter97={...LESSONS.infiltrationMine97,title:'布雷者：外围装备控制区不得包含敌人',source:'https://infinitythewiki.com/Minelayer',positions:[[20,30],[29,23]],overrides:[{...LESSONS.infiltrationMine97.overrides[0],infiltrationAttempt:false},{name:'敌方前沿模型',infiltration:true}],equipment:{a0:{loadout:['combi','cc','crazyKoala'],weapon:'combi',armyWeapons:{}}},instructions:'布雷者选CrazyKoala，(25,28)因8寸控制区含敌人拒绝，不扣库存；改放(15,30)成功、库存1/2，己方半场不需潜入骰。'};
LESSONS.impDeploySuccess97={...LESSONS.impDeploy81,pregame:{...LESSONS.impDeploy81.pregame,firstTurn:0},title:'伪装部署：敌部署区WIP成功保持IMP-1',instructions:'勾选进入敌部署区，选择IMP-1部署→锁定WIP检定，12/SV13成功。模型位置锁定且保持IMP-1，确认部署并完成后续步骤。',dice:[12]};

const mask98={ref:'teaching-sniper98',name:'狙击手外观（教学）',en:'IMITATED SNIPER',weapons:'狙击步枪（仅外观）',logo:'assets/zhanshi.svg'};
const masked98={name:'全息真身（教学）',en:'REAL BEARER',holoprojector:true,holomask:true,holoOptions:[mask98],holoAppearance:mask98,states:['holoecho','holomask'],bs:12,hp:3,maxhp:3,courage:true};
