LESSONS.holoPublic98={...LESSONS.holoDelay84,title:'全息组合：首次主动激活公开任一模型',reviewDate:'2026-10-25',positions:[[20,28],[24,20]],overrides:[masked98,{name:'蓝方观察者',hp:3,maxhp:3,courage:true}],extras:[fake98('echo98a',24,28),fake98('echo98b',28,28)],first:'idle',question:'公开回声标记必须放真身旁吗？',answer:'不需要。模型外观组合首次主动激活时，选三体中的任一个公开回声存在；不暴露真身。宣告攻击等取消状态，命令结束移除假体并换回真模型。',instructions:'先看三体均无公开回声标记；开始命令前选择外观模型甲为标记位置。Idle→蓝方延后→主动射击，蓝方只能反应真身；完成过保后两假体移除。',dice:[8,9,20,6,1,1]};
LESSONS.holoPublicIdle98={...LESSONS.holoPublic98,title:'全息组合：待机保留外观与公开标记',instructions:'选择模型乙为公开标记→Idle→蓝方延后→Idle。延后失效，不出现骰子；三体和公开标记保留，下一次主动激活不重新选择。',dice:[8]};
LESSONS.holoHidden98={...LESSONS.holoPublic98,title:'隐匿全息：三位置一并揭露与保留命令',overrides:[{...masked98,holomask:false,states:['hiddenDeployment','holoecho'],hiddenDeployment:true,hiddenOrderAvailable:true},{name:'蓝方观察者'}],extras:[{...fake98('echo98a',24,28),holomask:false,states:['hiddenDeployment','holoecho']},{...fake98('echo98b',28,28),holomask:false,states:['hiddenDeployment','holoecho']}],instructions:'地图上三个位置都隐藏。选择隐匿保留命令，Idle使三体同时出现；敌方延后，第二项Idle后失效。核对公共命令未扣、个人保留命令不再提供。',dice:[8]};
LESSONS.holoHiddenARO98={...LESSONS.holoHidden98,title:'隐匿全息：反应轮射击揭露整组',positions:[[20,28],[24,20]],overrides:[{...LESSONS.holoHidden98.overrides[0],bs:12},{name:'蓝方主动者',hp:3,maxhp:3,courage:true}],instructions:'先结束红回合。蓝方Idle，红真身用步枪ARO；三体一起显现，取消全息但假体保留至命令结束。蓝方Idle，步枪8命中1次、保1通过，最后假体全部移除。',dice:[8,1]};
LESSONS.holoHiddenBroken98={...LESSONS.holoHidden98,title:'隐匿全息：显现时立即检查一致性',extras:[{...LESSONS.holoHidden98.extras[0],x:34},{...LESSONS.holoHidden98.extras[1],x:38}],instructions:'使用保留命令激活。真身与两个假体均超过8寸一致性，真身状态立即取消，测量移动前假体全部移除。Idle+Idle结束；不允许仍操纵远处假体。'};
LESSONS.holoHiddenDeploy98={...LESSONS.holoDeploy84,title:'隐匿全息：部署记录全部回声位置',reviewDate:'2026-10-25',pregame:{...LESSONS.holoDeploy84.pregame,firstTurn:0},overrides:[{name:'隐匿全息部署兵',holoprojector:true,hiddenDeployment:true},{name:'远方观察者'}],instructions:'先选择隐匿部署，再放两个全息回声(24,40)、(28,40)。三者都不显示在地图上；部署确认后到开局，公共池不含真身，真身可用自己的保留命令。'};

LESSONS.syncAttack99={title:'同步附属：控制者射击、附属重喷，独立目标',kind:'N5.3 · Peripheral 官方示例结构',reviewDate:'2026-10-25',source:'https://infinitythewiki.com/Peripheral',question:'同一命令的同步附属必须和控制者打同一个目标吗？',answer:'不必。二者同一技能、各自武器、完整B和不同目标；反应者各选一个激活模型。直射模板与敌人射击不互相抵消，双方分别过保。',terrain:[],positions:[[18,28],[18,20]],overrides:[{name:'同步控制者',bs:12,hp:3,maxhp:3,courage:true},{name:'控制者的对手',bs:11,hp:3,maxhp:3,arm:0,courage:true}],extras:[{id:'sync99',name:'重喷附属',team:0,controllerId:'a0',peripheral:'synchronized',x:24,y:28,facing:-90,hp:2,maxhp:2,courage:true,noOrders:true,loadout:['heavyFlame','cc'],weapon:'heavyFlame'},{id:'other99',name:'附属的对手',team:1,x:24,y:23,facing:90,bs:11,hp:3,maxhp:3,arm:0,courage:true,loadout:['combi'],weapon:'combi'}],first:'idle',instructions:'Idle→两个敌人分别对控制者/附属步枪ARO→主动射击，控制者步枪打左敌，附属重喷打右敌。完整B3对1，重喷自动命中且对方独立射1骰；分别过保后结束。',dice:[9,10,20,6,8,1,1,1,1]};
LESSONS.ancillaryAttack99={...LESSONS.syncAttack99,title:'Ancillary：远离控制者仍独立射击完整B',positions:[[12,28],[12,20]],extras:[{...LESSONS.syncAttack99.extras[0],name:'远距Ancillary',peripheral:'ancillary',x:32,loadout:['combi','cc'],weapon:'combi'},{...LESSONS.syncAttack99.extras[1],x:32}],instructions:'Idle→两敌分别射击控制者和20寸外附属→控制者与附属各用自己的B3步枪打各自敌人，不因距离断连。各自生成3骰，对方各1骰，分别结算。',dice:[9,10,20,9,10,20,6,8,1,1,1,1]};
LESSONS.servantChoice99={...LESSONS.syncAttack99,title:'两名仆从：选择一名联动并远程接触救治',positions:[[12,28],[44,8]],overrides:[{name:'WIP14医生',doctor:true,wip:14},{name:'远处敌人',facing:45}],extras:[{id:'servant99a',name:'仆从甲',team:0,controllerId:'a0',peripheral:'servant',x:22,y:28,ph:9,noOrders:true,loadout:['cc'],weapon:'cc'},{id:'servant99b',name:'仆从乙',team:0,controllerId:'a0',peripheral:'servant',x:30,y:28,ph:9,noOrders:true,loadout:['cc'],weapon:'cc'},{id:'patient99',name:'乙旁昏迷友军',team:0,x:30+25/25.4,y:28,hp:0,maxhp:1,states:['unconscious'],attribute:'VITA',cube:true,noOrders:true,noARO:true,loadout:['combi'],weapon:'combi'}],first:'move',instructions:'选仆从乙，控制者Move0，再只有乙出现联动移动（选0寸），甲不激活。第二项医生，选乙旁伤员；以控制者WIP14掷8成功恢复，控制者本身不需接触。',dice:[8]};
LESSONS.servantARO99={...LESSONS.servantChoice99,title:'两名仆从：反应轮只选择一名执行同类ARO',positions:[[12,28],[26,22]],extras:LESSONS.servantChoice99.extras.slice(0,2),instructions:'结束红回合。蓝方Idle，选择仆从乙，甲显示未激活；医生和乙均Dodge。第二项Idle，分别一颗闪避骰，依次移动／原地，甲没有骰子也没有移动。',dice:[8,8]};
LESSONS.controlAttack99={...LESSONS.syncAttack99,title:'控制单元：只有控制者与指定先锋执行攻击',positions:[[12,28],[12,20]],extras:[{...LESSONS.syncAttack99.extras[0],id:'control99a',name:'控制附属甲',peripheral:'control',x:28,y:28,loadout:['combi'],weapon:'combi'},{...LESSONS.syncAttack99.extras[0],id:'control99b',name:'控制附属乙',peripheral:'control',x:32,y:28,loadout:['combi'],weapon:'combi'},{...LESSONS.syncAttack99.extras[1],x:32}],instructions:'选择乙为先锋。Idle→敌方均放弃→控制者射击左敌、乙射击右敌；甲虽被激活但攻击待机，没有第三组骰。两名执行者各B3，命令结束只扣1正规。',dice:[9,10,20,9,10,20,1,1,1,1]};
LESSONS.controlNull99={...LESSONS.controlAttack99,title:'控制单元：先锋昏迷立即改选，再处理后续阶段',extras:[{...LESSONS.controlAttack99.extras[0]},{...LESSONS.controlAttack99.extras[1],hp:1,maxhp:1,arm:0},{...LESSONS.controlAttack99.extras[2]}],instructions:'乙先锋，Idle→右敌步枪反应打乙、左敌放弃→Idle。骰8命中、过保20失败乙昏迷；必须立即点选甲为新先锋后，才能继续结束命令。',dice:[8,20]};
LESSONS.ancillarySplit99={...LESSONS.ancillaryAttack99,title:'附属联动：控制者B4分2+2，附属保留自身B3',positions:[[20,28],[18,18]],extras:[{...LESSONS.ancillaryAttack99.extras[0],x:30,y:28},{...LESSONS.ancillaryAttack99.extras[1],x:26,y:20}],equipment:{a0:{loadout:['hmg','cc'],weapon:'hmg'}},instructions:'Idle，两敌均放弃。控制者重机枪B4分别分2+2给两敌，Ancillary步枪B3独立打右敌；应出现2、2、3三组攻击骰，各自修正、过保；全部结束只消耗1个公共命令。',dice:[7,8,7,8,9,10,20,1,1,1,1,1,1]};
LESSONS.friendlyCoord100={...LESSONS.friendlyFire80,title:'协调命令：两名射手分别分配射入近战的失败骰',reviewDate:'2026-10-25',extras:[...LESSONS.friendlyFire80.extras,{id:'wing100',name:'协调第二射手',team:0,x:23,y:28,facing:-90,bs:14,hp:3,maxhp:3,courage:true,loadout:['combi'],weapon:'combi'}],instructions:'勾选本人和第二射手，花1正规+1指挥令。Idle→敌放弃→两人Combi打同一近战目标。先锋B2骰3/8，成员B1骰20，SV5；将失败8分给友军甲、失败20分给友军乙。敌方、甲、乙各过保一次；两名射手的失误不能合并或漏掉。',dice:[3,8,20,1,1,1]};

LESSONS.peripheralImm101={...LESSONS.ancillaryAttack99,title:'FAQ：控制者IMM-B，附属仍可移动和射击',reviewDate:'2026-10-25',question:'控制者不能宣告行动，就不能激活附属了吗？',answer:'仍能。FAQ v0.1规定同组宣告同一技能，各自不能执行者按Idle处理。选择附属作为操作焦点不会使它产生额外命令。',overrides:[{...LESSONS.ancillaryAttack99.overrides[0],name:'IMM-B控制者',states:['immB']},{...LESSONS.ancillaryAttack99.overrides[1]}],first:'move',instructions:'控制者面板点“通过远距Ancillary操作本组”→Move0→控制者联动Idle。左敌射控制者，右敌射附属。附属BS打右敌B3；控制者因IMM-B待机，左敌对控制者为普通骰，不被附属射击抵消。只扣控制者1正规命令。',dice:[9,10,20,6,8,1,1,1]};
LESSONS.peripheralStun101={...LESSONS.peripheralImm101,title:'FAQ：控制者眩晕，附属仍可独立攻击',overrides:[{...LESSONS.peripheralImm101.overrides[0],name:'眩晕控制者',states:['stunned']},{...LESSONS.peripheralImm101.overrides[1]}],instructions:'点通过附属操作本组→Move0→控制者Move0。两个敌人分别射击控制者和附属。附属正常B3，控制者眩晕攻击待机；左敌独立普通骰，右敌与附属拼骰，分别过保并结束。'};

LESSONS.existingStunGuts101={title:'勇气：已有眩晕再受普通攻击，WIP−3',kind:'N5.3 · 状态与弹药时点',reviewDate:'2026-10-25',source:'https://infinitythewiki.com/Guts_Roll',question:'已经眩晕会让后续全部勇气自动失败吗？',answer:'不会。本次眩晕弹药过保失败才强制败勇气（勇敢/等效技能例外）；已有眩晕再遭普通攻击时，WIP检定仍受眩晕−3。',terrain:[],positions:[[20,28],[20,20]],overrides:[{name:'已有眩晕教学兵',states:['stunned'],wip:13,courage:false,religious:false,hp:3,maxhp:3},{name:'步枪反应者',courage:false,loadout:['combi'],weapon:'combi'}],first:'idle',instructions:'Idle→敌Combi反应→Idle。敌骰8命中，保1成功后进入勇气选择，不得直接自动失败。点掷WIP，11对SV10失败；无掩体可逃，确认俯卧后结束。',dice:[8,1,11]};
LESSONS.newStunGuts101={...LESSONS.existingStunGuts101,title:'勇气：本次眩晕弹药过保失败，自动失败',overrides:[{...LESSONS.existingStunGuts101.overrides[0],name:'本次被眩晕教学兵',states:[]},{name:'闪光反应者',courage:false,loadout:['flash'],weapon:'flash'}],equipment:{b0:{loadout:['flash'],weapon:'flash',armyWeapons:{}}},instructions:'Idle→敌Flash Pulse反应→Idle。骰8命中，BTS过保20失败进入眩晕；勇气直接自动失败、不额外掷WIP，确认无路后俯卧。',dice:[8,20]};

LESSONS.newStunCourage101={...LESSONS.newStunGuts101,title:'勇气：眩晕弹药失败，勇敢可自动坚守',overrides:[{...LESSONS.newStunGuts101.overrides[0],name:'勇敢教学兵',courage:true},{...LESSONS.newStunGuts101.overrides[1]}],instructions:'Idle→闪光ARO→Idle；8命中，20过保失败进入眩晕。勇敢保留自动成功选项，选择坚守，无移动不俯卧。'};
LESSONS.newStunReligious101={...LESSONS.newStunGuts101,title:'勇气：虔信遇眩晕，撤离须过WIP−3',overrides:[{...LESSONS.newStunGuts101.overrides[0],name:'虔信教学兵',religious:true},{...LESSONS.newStunGuts101.overrides[1]}],instructions:'Idle→闪光ARO→Idle；8命中，20过保失败。虔信不能自动失败；申请撤离掷11对SV10失败，须坚守，无俯卧。',dice:[8,20,11]};

const cpProfiles102={connected:{s:2,type:'REM',mov:6,mov2:4,bs:14,cc:12,ph:11,wip:15,arm:1,bts:3,maxhp:2,attribute:'STR',loadout:['combi','cc'],weapon:'combi',courage:true},autonomous:{s:2,type:'REM',mov:4,mov2:4,bs:8,cc:8,ph:9,wip:9,arm:0,bts:0,maxhp:2,attribute:'STR',loadout:['pistol','cc'],weapon:'pistol',courage:true}};
const cpUnit102=(id,x)=>({id,name:id==='cp102a'?'Cyberplug甲':'Cyberplug乙',team:0,controllerId:'a0',peripheral:'cyberplug',cyberplugProfiles:cpProfiles102,x,y:28,facing:-90,hp:2,maxhp:2,noOrders:true,loadout:['combi','cc'],weapon:'combi'});
LESSONS.cyberConnected102={title:'Cyberplug：连接配置攻击，控制者Idle',kind:'N5.3 · 明确教学双配置',reviewDate:'2026-10-25',source:'https://infinitythewiki.com/Peripheral',question:'Cyberplug连接配置与一般附属有什么不同？',answer:'连接模型与控制者使用同一命令，但控制者Idle（Doctor/Engineer例外）；其余模型自主，可独立消耗本组公共命令与执行ARO。本例双配置为明确教学覆写，不替换导入军表。',terrain:[],positions:[[20,28],[26,20]],overrides:[{name:'Cyberplug控制者',cyberplug:true,hp:3,maxhp:3,courage:true},{name:'连接模型的对手',hp:3,maxhp:3,courage:true}],extras:[cpUnit102('cp102a',26),cpUnit102('cp102b',32),{id:'cpEnemy102',name:'看见控制者的对手',team:1,x:20,y:20,facing:90,bs:11,hp:3,maxhp:3,courage:true,loadout:['combi'],weapon:'combi'}],first:'move',instructions:'甲连接，开始命令自动以甲操作。甲Move0→控制者Idle，乙不激活。两个敌人分别射甲／控制者；甲Combi B3对正前方，控制者0骰。分别拼骰和普通骰，过保后结束。',dice:[9,10,20,6,8,1,1,1]};
LESSONS.cyberAutonomous102={...LESSONS.cyberConnected102,title:'Cyberplug：自主配置独立命令与自身武器',positions:[[20,28],[32,24]],extras:[cpUnit102('cp102a',26),cpUnit102('cp102b',32)],first:'idle',instructions:'选择全部自主，再点乙，命令来源为本组正规，不经控制者。Idle→敌放弃→乙仅手枪，B2/SV11；不能借用连接配置的Combi或BS14。完成过保/勇气后只扣1正规，其他模型未激活。',dice:[8,20,1]};
LESSONS.cyberAROSwap102={...LESSONS.cyberConnected102,title:'Cyberplug：ARO交换连接配置，其余自主闪避',positions:[[20,28],[28,22]],extras:[cpUnit102('cp102a',26),cpUnit102('cp102b',32)],instructions:'结束红回合，蓝Idle。ARO前把连接从甲换为乙；控制者Idle、乙Combi射击、甲自主Dodge，不要求两附属同技能。蓝Idle后，乙使用连接BS14，甲自主PH9并进入闪避移动。',dice:[8,8,1]};
LESSONS.cyberAROIndependent102={...LESSONS.cyberAROSwap102,title:'Cyberplug：控制者正常ARO时两附属全部自主',instructions:'蓝Idle后选全部自主。控制者Dodge、甲Pistol射击、乙Reset，分别可选且互不约束。甲只有自主武器与BS8；宣告首个反应后配置不能再换。蓝Idle后分别检定并结束。',dice:[8,8,8,1]};
LESSONS.cyberNull102={...LESSONS.cyberConnected102,title:'Cyberplug：控制者昏迷后全部自主仍可激活',overrides:[{...LESSONS.cyberConnected102.overrides[0],hp:1,maxhp:1,arm:0},{...LESSONS.cyberConnected102.overrides[1]}],first:'idle',instructions:'甲连接Idle→控制者面前敌人Combi射控制者，另一敌放弃→Idle。8命中、20过保令控制者昏迷，命令结束两附属改自主，不断连。再选乙，用剩余正规命令Idle+Idle完整激活。',dice:[8,20]};
LESSONS.cyberDoctor102={...LESSONS.cyberConnected102,route:[{x:26,y:28,z:0},{x:26,y:29,z:0},{x:26,y:28,z:0}],title:'Cyberplug：连接接触救治使用控制者WIP',positions:[[12,28],[44,8]],overrides:[{...LESSONS.cyberConnected102.overrides[0],doctor:true,wip:14},{name:'远处观察者',facing:45}],extras:[cpUnit102('cp102a',26),cpUnit102('cp102b',32),{id:'cpPatient102',name:'连接甲旁伤员',team:0,x:26+25/25.4,y:28,facing:-90,hp:0,maxhp:1,attribute:'VITA',states:['unconscious'],noOrders:true,noARO:true,loadout:['combi'],weapon:'combi'}],instructions:'甲连接，示例路线往返2寸后仍接触伤员，控制者Idle，观察者放弃。第二项Doctor以甲接触伤员，使用控制者WIP14（不是甲的15），骰8成功恢复1/1。',dice:[8]};
LESSONS.cyberRecovery102={...LESSONS.cyberConnected102,title:'Cyberplug：控制者解除孤立，命令末选择重连',positions:[[20,28],[44,8]],overrides:[{...LESSONS.cyberConnected102.overrides[0],type:'REM',attribute:'STR',states:['isolated']},{name:'远方敌人',facing:45}],extras:[cpUnit102('cp102a',26),cpUnit102('cp102b',32),{id:'cpEngineer102',name:'恢复控制者的工程师',team:0,x:20-25/25.4,y:28,facing:-90,engineer:true,wip:14,hp:2,maxhp:2,courage:true,loadout:['combi'],weapon:'combi'}],first:'idle',instructions:'起始控制者孤立，两附属均自主。点工程师Idle，敌放弃，Engineer解除控制者孤立，8成功；命令结束必须从甲/乙选择一个连接，选乙；控制者恢复待机规则，甲仍自主。',dice:[8]};

LESSONS.cyberProfileLoF102={...LESSONS.cyberAROSwap102,title:'Cyberplug：按切换后的360目镜重新检查ARO',positions:[[12,28],[32,38]],overrides:[{...LESSONS.cyberConnected102.overrides[0]},{...LESSONS.cyberConnected102.overrides[1],facing:-90}],extras:[cpUnit102('cp102a',20),{...cpUnit102('cp102b',32),cyberplugProfiles:{connected:{...cpProfiles102.connected,visor360:true},autonomous:{...cpProfiles102.autonomous,visor360:false}}}],instructions:'结束红回合，蓝Idle。敌人在乙背后10寸，乙自主时没有ARO；宣告前选乙连接，连接配置360目镜使它获得视线，允许Combi ARO。甲和控制者仍无资格。蓝Idle，8命中/保1通过，完成勇气。',dice:[8,1]};
LESSONS.cyberDeploy102={...LESSONS.cyberConnected102,title:'Cyberplug：部署一连接一自主，再开始游戏',positions:[[20,40],[35,5]],extras:[{...cpUnit102('cp102a',24),y:40},{...cpUnit102('cp102b',28),y:40}],pregame:{stage:'deploy',firstDeployment:0,firstTurn:0,step:0,reserves:{0:[],1:[]},sides:{0:'south',1:'north'}},editableDeploy:true,instructions:'红方部署时把乙选为连接，甲自主；部署选择器不允许全部自主。将控制者设为保留模型，两附属随它保留且只占一个名额。红主部署0人→蓝主部署1人→红保留逐个确认三模型→蓝保留0人；跳过双方Speedball后开局，红正规池应为1。'};

LESSONS.controlExplode103={...LESSONS.controlAttack99,title:'控制先锋：后续自爆致昏迷，下一波前立即改选',kind:'N5.3 · Control与Explode组合',question:'后续自爆导致先锋失能，何时选择新先锋？',answer:'每一波伤害后立即检查；先锋进入Null便先指定新先锋，再处理下一波。休克免疫保留昏迷分支，普通1VITA模型因Shock直接移除时不触发Explode。',reviewDate:'2026-10-25',positions:[[12,32],[30,22]],overrides:[{name:'控制者',bs:12,hp:3,maxhp:3,courage:true},{name:'第一波蓝方自爆兵',hp:1,maxhp:1,arm:0,explode:true,loadout:['cc'],weapon:'cc'}],extras:[{...LESSONS.controlAttack99.extras[0],x:24,y:24,hp:2,maxhp:2},{...LESSONS.controlAttack99.extras[1],x:30,y:24,hp:1,maxhp:1,arm:0,shockImmune:true,explode:true,loadout:['cc'],weapon:'cc'},{id:'chain103',name:'蓝方连锁目标',team:1,x:32.5,y:24,facing:180,hp:1,maxhp:1,arm:0,explode:true,loadout:['cc'],weapon:'cc'}],instructions:'乙为先锋。控制者Idle→两敌放弃→步枪射第一波蓝兵，乙无射击武器而Idle。8/20/20一命中，保20后蓝兵自爆。第一波保20令休克免疫的乙昏迷，必须先选甲为先锋，才能进行乙第二波自爆；末端蓝兵保20因无休克免疫而直接移除，不触发第三波。检查甲仍为先锋，只扣1正规。',dice:[8,20,20,20,20,20]};

LESSONS.controlExplodeImmune103={...LESSONS.controlExplode103,title:'控制先锋：休克免疫保留第三波自爆',extras:[...LESSONS.controlExplode103.extras.slice(0,2),{...LESSONS.controlExplode103.extras[2],name:'第三波休克免疫自爆兵',shockImmune:true}],instructions:'乙先锋，Idle→两敌放弃→控制者BS射第一波蓝兵。骰8/20/20一命中，保20进入第一波；乙保20昏迷后先指定甲。第二波末端蓝兵因休克免疫，保20进入昏迷而非直接移除；确认第三波空模板无需过保即结束。甲仍为先锋，公共命令3→2。'};

