const patient104=(id,x,extra={})=>({id,name:id==='patient104c'?'控制者旁伤员':'先锋旁伤员',team:0,x:x+25/25.4,y:28,facing:-90,s:2,hp:0,maxhp:1,attribute:'VITA',states:['unconscious'],noOrders:true,noARO:true,loadout:['cc'],weapon:'cc',...extra});
LESSONS.controlDoctor104={title:'Control：医生逐成员选不同目标',kind:'N5.3 · 逐成员技能宣告',reviewDate:'2026-10-25',source:'https://infinitythewiki.com/Peripheral',question:'非射击技能是否也受先锋限制？',answer:'主动轮凡需要目标的技能，只有控制者与先锋执行。各自需要具备技能，各选目标、位置并分别检定。无目标技能不受先锋限制；ARO不适用主动轮先锋限制。此场景技能为明确教学覆写。',terrain:[],positions:[[20,28],[44,8]],overrides:[{name:'Control控制者',doctor:true,engineer:true,wip:14,hp:3,maxhp:3,courage:true},{name:'远处观察者',facing:45}],extras:[controlMember104('cu104a',24,{doctor:true,engineer:true}),controlMember104('cu104b',28,{doctor:true,engineer:true}),patient104('patient104c',20),patient104('patient104a',24)],first:'idle',instructions:'Idle→敌方放弃→Doctor。控制者选择身旁伤员，确认后才轮到甲，选择甲旁伤员。乙虽有Doctor但非先锋，自动待机。8/9两颗WIP分别救醒两人。',dice:[8,9]};
LESSONS.controlEngineer104={...LESSONS.controlDoctor104,title:'Control：工程师仅先锋有技能也可发起',overrides:[{...LESSONS.controlDoctor104.overrides[0],doctor:false,engineer:false},LESSONS.controlDoctor104.overrides[1]],extras:[controlMember104('cu104a',24,{engineer:true}),controlMember104('cu104b',28,{engineer:true}),patient104('patient104a',24,{attribute:'STR',remotePresence:true,hp:-1,states:['unconscious2']})],instructions:'控制者无Engineer但甲有。Idle后仍能选Engineer；控制者待机，甲修复身旁昏迷II遥控机，乙非先锋待机。8成功直接恢复1 STR。',dice:[8]};
LESSONS.controlDiscover104={...LESSONS.controlDoctor104,title:'Control：首项／第二项Discover独立目标',positions:[[20,28],[20,22]],overrides:[{...LESSONS.controlDoctor104.overrides[0]},{name:'左侧迷彩',camouflage:true,states:['camouflaged'],mim:3}],extras:[controlMember104('cu104a',24),controlMember104('cu104b',28),{id:'marker104',name:'右侧迷彩',team:1,x:28,y:22,facing:90,camouflage:true,states:['camouflaged'],mim:3,loadout:['combi'],weapon:'combi'}],instructions:'首项选Discover（或Idle后第二项Discover）。控制者选左迷彩，甲选右迷彩；乙待机。敌方放弃，第二项Idle。分别8/9两骰揭露不同目标。',dice:[8,9]};
LESSONS.controlSensor104={...LESSONS.controlDiscover104,title:'Control：Sensor无目标，全体有技能者执行',overrides:[{...LESSONS.controlDoctor104.overrides[0],sensor:true},LESSONS.controlDiscover104.overrides[1]],extras:[controlMember104('cu104a',24,{sensor:true}),controlMember104('cu104b',28,{sensor:true}),LESSONS.controlDiscover104.extras[2]],instructions:'Idle→两迷彩放弃→Sensor。依次确认控制者、甲、非先锋乙。三人各一颗WIP+6（8/9/10），每个人覆盖多个标记仍只掷自己的这一颗。',dice:[8,9,10]};
LESSONS.controlDeploy104={...LESSONS.controlDoctor104,title:'Control：三成员分别放置自身部署物',overrides:[{...LESSONS.controlDoctor104.overrides[0],deployableItems:['deployableRepeater']},LESSONS.controlDoctor104.overrides[1]],extras:[controlMember104('cu104a',24,{deployableItems:['shockMine']}),controlMember104('cu104b',28,{deployableItems:['deployableRepeater']})],instructions:'Idle后选放置。依次在(20,29)、(24,29)、(28,29)点击并确认：控制者中继器、甲地雷、乙中继器。非先锋也执行；每人仅扣自身1次库存，命令末放置三枚，无命中/过保。',dice:[8]};
LESSONS.controlReload104={...LESSONS.controlDeploy104,title:'Control：装填逐成员但仅一名获得补给',overrides:[{...LESSONS.controlDeploy104.overrides[0],baggage:true},LESSONS.controlDoctor104.overrides[1]],extras:[controlMember104('cu104a',24,{deployableItems:['shockMine'],spentWeapons:{shockMine:2}}),controlMember104('cu104b',28,{deployableItems:['deployableRepeater'],spentWeapons:{deployableRepeater:2}})],instructions:'Idle后装填，控制者未消耗装备自动待机；在待宣告成员中改选乙，确认乙装填。甲本令只能待机；检查乙恢复3/3，甲仍1/3。',dice:[8]};
LESSONS.controlDeployARO104={...LESSONS.controlDeploy104,title:'Control：ARO部署需各自LoF，非先锋可用',positions:[[20,28],[24,22]],overrides:[{...LESSONS.controlDeploy104.overrides[0],facing:90}, {name:'蓝方主动兵',facing:90,hp:3,maxhp:3,courage:true}],instructions:'结束红回合，蓝Idle。背对敌人的控制者只有ZoC无LoF，不能放置；甲和非先锋乙均有LoF，可分别放地雷／中继器。ARO菜单不提供Doctor、Engineer、Sensor。蓝Idle，命令末两枚放置。'};
LESSONS.controlDiscoverARO104={...LESSONS.controlDiscover104,title:'Control：ARO Discover非先锋也能执行',positions:[[20,28],[24,22]],overrides:[{...LESSONS.controlDoctor104.overrides[0],facing:90}, {...LESSONS.controlDiscover104.overrides[1],name:'蓝方主动迷彩',facing:90}],extras:LESSONS.controlDiscover104.extras.slice(0,2),instructions:'结束红回合，蓝迷彩Idle。控制者放弃，甲和非先锋乙均Discover同一主动迷彩；蓝Idle。两人分别普通WIP检定，不因非先锋删掉乙的宣告。',dice:[8,9]};
LESSONS.controlNWI105={...LESSONS.controlExplode103,title:'多重生存：先锋选NWI，保留先锋并抑制自爆',extras:[LESSONS.controlExplode103.extras[0],{...LESSONS.controlExplode103.extras[1],nwi:true,dogged:true},LESSONS.controlExplode103.extras[2]],instructions:'乙先锋；控制者击倒第一蓝兵→第一波自爆使乙昏迷。乙可选NWI／顽强／不用：选NWI，不要求换先锋，不触发乙自爆；末端蓝兵保留。'};
LESSONS.controlSurvivalChain105={...LESSONS.controlNWI105,title:'多重生存：放弃→换先锋→下波选择顽强',extras:[...LESSONS.controlNWI105.extras.slice(0,2),{...LESSONS.controlNWI105.extras[2],shockImmune:true,nwi:true,dogged:true}],instructions:'乙先锋，第一波后乙不启用生存技能→先选甲新先锋→乙第二波使末端蓝兵昏迷。末端选顽强，取消第三波。回合状态阶段顽强移除，不补触发自爆。'};
LESSONS.multiSurvival105={...LESSONS.controlAttack99,title:'多重生存：同波三个选择全部确认后再连锁',positions:[[12,28],[12,22]],overrides:[{name:'主动控制者',bs:12,hp:3,maxhp:3,courage:true},{name:'左侧NWI目标',hp:1,maxhp:1,arm:0,nwi:true,dogged:true,shockImmune:true,courage:true}],extras:[{...LESSONS.controlAttack99.extras[0],x:24,y:28},{...LESSONS.controlAttack99.extras[1],x:32,y:28,hp:1,maxhp:1,arm:0,nwi:true,dogged:true,shockImmune:true,explode:true},{...LESSONS.controlAttack99.extras[2],x:32,y:26,name:'右侧顽强连锁源',hp:1,maxhp:1,arm:0,nwi:true,dogged:true,shockImmune:true,explode:true}],equipment:{a0:{loadout:['combi'],weapon:'combi'},b0:{loadout:['combi'],weapon:'combi'}},instructions:'乙先锋。Idle→左蓝放弃，右蓝以重喷ARO攻击乙→控制者Combi左蓝，乙Combi右蓝。各一命中，主动模板伤与射击同时生效。按顺序左蓝NWI、乙NWI、右蓝不用；只有全部选择后才进入右蓝自爆，乙再次受伤直接移除、换甲先锋，乙不再自爆。',dice:[8,20,20,8,20,20,20,20,20,1,20]};
LESSONS.multiSurvival105.extras[2].loadout=['heavyFlame','cc'];LESSONS.multiSurvival105.extras[2].weapon='heavyFlame';
LESSONS.controlMedikit104={...LESSONS.controlDoctor104,title:'Control：医疗包逐成员接触不同伤员',overrides:[{...LESSONS.controlDoctor104.overrides[0],medikit:true},LESSONS.controlDoctor104.overrides[1]],extras:[controlMember104('cu104a',24,{medikit:true}),controlMember104('cu104b',28,{medikit:true}),patient104('patient104c',20,{ph:12}),patient104('patient104a',24,{ph:10})],instructions:'Idle后医疗包，控制者与甲各选身旁伤员并使用轮廓接触模式；乙待机。两个伤员各做自己的PH检定8/9，通过后分别恢复1。'};
LESSONS.controlGizmo104={...LESSONS.controlMedikit104,title:'Control：维修包各自选择修复或技术恢复',overrides:[{...LESSONS.controlDoctor104.overrides[0],gizmokit:true},LESSONS.controlDoctor104.overrides[1]],extras:[controlMember104('cu104a',24,{gizmokit:true}),controlMember104('cu104b',28,{gizmokit:true}),patient104('patient104c',20,{attribute:'STR',remotePresence:true,hp:-1,states:['unconscious2'],ph:12}),patient104('patient104a',24,{attribute:'STR',hp:1,techRecovery:true,states:['immB','isolated'],ph:10})],instructions:'控制者维修包接触修复昏迷II，甲维修包接触选择技术恢复，解除另一人IMM-B/孤立；非先锋乙待机。各目标PH检定8/9后检查状态。'};
LESSONS.controlSpeedball104={...LESSONS.controlDoctor104,title:'Control：各自使用持有的Speedball补给',overrides:[{...LESSONS.controlDoctor104.overrides[0],speedballItem:'vita'},LESSONS.controlDoctor104.overrides[1]],extras:[controlMember104('cu104a',24,{speedballItem:'repairs'}),controlMember104('cu104b',28,{speedballItem:'vita'}),patient104('patient104c',20),patient104('patient104a',24,{attribute:'STR',hp:-1,states:['unconscious2'],remotePresence:true})],instructions:'控制者持生命包、甲持维修包、乙持生命包。Idle后分别救治自己的接触伤员，无骰；控制者和甲消耗自己的补给，非先锋乙待机并保留生命包。'};
LESSONS.controlDeactivator104={...LESSONS.controlDoctor104,title:'Control：拆除器各自选择敌方部署物',overrides:[{...LESSONS.controlDoctor104.overrides[0],deactivator:true},LESSONS.controlDoctor104.overrides[1]],extras:[controlMember104('cu104a',24,{deactivator:true}),controlMember104('cu104b',28,{deactivator:true}),{id:'device104c',name:'左侧敌方中继器',team:1,x:20,y:24,s:1,isDeployable:true,deployableKind:'deployableRepeater',noOrders:true,noARO:true,loadout:[],weapon:'cc'},{id:'device104a',name:'右侧敌方中继器',team:1,x:24,y:24,s:1,isDeployable:true,deployableKind:'deployableRepeater',noOrders:true,noARO:true,loadout:[],weapon:'cc'}],instructions:'Idle后拆除器，控制者选左部署物，甲选右部署物；各WIP+6，8/9成功移除目标，无过保。乙不执行。'};
LESSONS.controlMission104={...LESSONS.controlDoctor104,title:'Control：任务目标按各自专家资格宣告',positions:[[12,25.28],[44,8]],extras:[controlMember104('cu104a',24,{y:25.28,specialist:true}),controlMember104('cu104b',28,{y:25.28,specialist:true})],objectives:[{id:'console0',name:'西控制台',kind:'console',x:12,y:24,r:20/25.4,owner:null},{id:'console1',name:'中央控制台',kind:'console',x:24,y:24,r:20/25.4,owner:null}],instructions:'使用Hardlock控制台接触/WIP规则的明确教学位置。控制者Doctor激活西控制台，甲有Specialist教学技能激活中央控制台；乙非先锋待机。分别WIP14/12与8/9成功。'};
LESSONS.controlReloadARO104={...LESSONS.controlReload104,title:'Control：无LoF也可装填ARO，但只有一人受益',activeTeam:1,positions:[[20,28],[24,22]],overrides:[{...LESSONS.controlReload104.overrides[0],facing:90},{name:'蓝方主动兵',hp:3,maxhp:3,facing:90}],extras:LESSONS.controlReload104.extras.map(u=>({...u,facing:90})),instructions:'蓝方开局（省略已完成的上一回合）。蓝Idle，红三人均只有ZoC，没有LoF。甲有装填ARO；确认甲装填后乙不能再装填。控制者与乙放弃，蓝Idle后甲恢复3/3，乙保持1/3。'};
LESSONS.survivalDodge105={title:'NWI：受通讯攻击后保留成功闪避移动',kind:'N5.3 · 生存与Dodge顺序',reviewDate:'2026-10-25',source:'https://infinitythewiki.com/Dodge',question:'成功闪避但遭黑客致伤，启用NWI后还能移动吗？',answer:'Dodge不规避通讯攻击，双方分别普通检定。启用NWI后模型仍可行动；其已经成功的闪避检定应保留，随后执行闪避移动。',terrain:[],positions:[[20,28],[20,22]],overrides:[{name:'NWI黑客',hackingDevice:'HD',nwi:true,hp:1,maxhp:1,bts:0,ph:12,courage:true},{name:'Trinity反应黑客',hackingDevice:'KHD',wip:13,hp:3,maxhp:3,courage:true}],first:'idle',instructions:'红Idle→蓝Trinity ARO→红第二项Dodge。红8/PH12成功、蓝9/WIP16普通命中；红过保20受1伤后选NWI。必须出现2寸闪避移动，实际向右走1寸，再完成勇气。',dice:[8,9,20]};
Object.assign(LESSONS.controlNWI105,{source:'https://infinitythewiki.com/No_Wound_Incapacitation',question:'先锋受伤后可启用NWI时，需要先更换先锋吗？',answer:'先确认是否启用生存技能。NWI／顽强忽略昏迷的Null标签，因此仍可行动、不需更换先锋，并抑制自身Explode；不启用时才按最终Null状态换先锋。明确教学组合不改写导入军表。'});
Object.assign(LESSONS.controlSurvivalChain105,{source:'https://infinitythewiki.com/Explode',question:'后续波次又出现生存选择，是否可以跳过？',answer:'每一波先完成该波所有生存选择，再检查最终Null状态、先锋和下一波自爆。顽强在当前玩家回合状态阶段直接移除，不因此触发Explode。'});
Object.assign(LESSONS.multiSurvival105,{source:'https://infinitythewiki.com/Explode',kind:'N5.3 · 同波生存与连锁',question:'同一波有多名模型可用NWI／顽强，何时开始自爆？',answer:'先逐一确定同波最终状态。选择NWI／顽强的模型不自爆；选择昏迷且具备Explode者才进入后续自爆。NWI再次受伤直接移除，没有第二次选择或自爆。'});
LESSONS.multiSurvival105.instructions+=' 重喷第一次过保20失败，持续伤害追加过保1通过，乙只受1伤。';

LESSONS.controlSupport106={...LESSONS.controlDoctor104,title:'Control：整令支援各选REM，非先锋待机',reviewDate:'2026-10-27',source:'https://infinitythewiki.com/Enhanced_Reaction',overrides:[{name:'EVO控制者',hackingDevice:'EVO',wip:14,hp:3,maxhp:3,courage:true},{name:'远方观察者',facing:45}],extras:[controlMember104('cu104a',24,{hackingDevice:'EVO'}),controlMember104('cu104b',28,{hackingDevice:'EVO'}),{...patient104('patient104c',20),name:'左侧REM',type:'REM',hp:1,states:[],attribute:'STR'},{...patient104('patient104a',24),name:'右侧REM',type:'REM',hp:1,states:[],attribute:'STR'}],first:'program:enhancedReaction',question:'Control的支援程序是否可借用其他成员的设备？',answer:'不能。每名执行者需要自己的程序，分别指定目标；主动轮有目标的程序只有控制者与先锋执行。强化反应是整令，无第二项技能，不能用于ARO。此处EVO均为明确教学配置。',instructions:'首项选择强化反应整令，控制者选左侧REM，甲选右侧REM，乙自动待机。全部宣告后才进入首次ARO，放弃后直接结算，无第二项行动、无骰。两个REM获得ARO B2。',dice:[8]};
LESSONS.controlSupportOnly106={...LESSONS.controlSupport106,title:'Control：只有先锋有EVO，控制者仍可发起',overrides:[{...LESSONS.controlSupport106.overrides[0],name:'无设备控制者',hackingDevice:null},LESSONS.controlSupport106.overrides[1]],instructions:'控制者没有黑客设备，首项仍能选先锋的强化反应整令；控制者待机，甲选右侧REM，乙非先锋待机。仅甲的程序生效。'};
LESSONS.controlFairy106={...LESSONS.controlSupport106,title:'Control：仙尘各选兵种，全桌效果',first:'program:fairyDust',source:'https://infinitythewiki.com/Fairy_Dust',extras:[...LESSONS.controlSupport106.extras.slice(0,3),{...LESSONS.controlSupport106.extras[3],type:'HI',name:'右侧HI'}],instructions:'仙尘整令：控制者选REM，甲选HI；乙非先锋待机。两种兵种分别获得Firewall −3，范围为全桌。'};
LESSONS.controlJump106={...LESSONS.controlSupport106,title:'Control：跳跃控制无目标，宣告立即生效',first:'idle',source:'https://infinitythewiki.com/Controlled_Jump',instructions:'Idle后选黑客支援，三名EVO逐个宣告跳跃控制；非先锋也可执行，每次宣告立即生效，同方始终只保留一个跳跃控制。最后由乙维持；全部声明完才继续ARO，不掷骰。'};
LESSONS.controlSupportARO106={...LESSONS.controlSupport106,title:'Control：ARO只有跳跃控制，没有整令支援',activeTeam:1,positions:[[20,28],[24,22]],overrides:[{...LESSONS.controlSupport106.overrides[0],facing:90},{name:'蓝方主动兵',facing:90,hp:3,maxhp:3,courage:true}],extras:LESSONS.controlSupport106.extras.slice(0,2).map(v=>({...v,facing:90})),instructions:'蓝方Idle，红三人均只有ZoC无LoF。ARO不提供辅助射击、强化反应或仙尘，但可用跳跃控制；甲放弃，控制者与乙分别宣告跳跃控制，立即生效且同方只保留一个。蓝Idle完整结束。'};
LESSONS.controlSupportRange106={...LESSONS.controlSupport106,title:'Control：逐成员黑客范围结算，禁止借用范围',extras:[...LESSONS.controlSupport106.extras.slice(0,3),{...LESSONS.controlSupport106.extras[3],x:38,name:'远处REM'}],instructions:'控制者宣告支援左侧REM，甲宣告支援远处REM；宣告不提前测距。结算控制者成功，甲因自己的黑客范围不足转待机，不借用其他人的范围。'};

LESSONS.syncEngineer107={...LESSONS.controlEngineer104,title:'同步附属：两个工程师分别修复，不限先锋',reviewDate:'2026-10-27',overrides:[{...LESSONS.controlDoctor104.overrides[0],name:'同步工程师控制者'},LESSONS.controlDoctor104.overrides[1]],extras:[{...controlMember104('cu104a',24,{engineer:true}),peripheral:'synchronized',name:'同步附属工程师'},patient104('patient104c',20,{attribute:'STR',remotePresence:true,hp:-1,states:['unconscious2']}),patient104('patient104a',24,{attribute:'STR',remotePresence:true,hp:-1,states:['unconscious2']})],question:'同步附属执行有目标技能，也受到Control先锋限制吗？',answer:'不受。控制者与同步附属同一技能，各自具备能力时可分别选目标；Servant远程医生／工程师例外仍由控制者仅救治一个目标。此场景是显式教学能力，不修改导入军表。',instructions:'Idle后选Engineer，控制者与同步附属分别选择各自旁边的昏迷II遥控机修复，8/9成功后两人都恢复1STR。',dice:[8,9]};
LESSONS.ancillaryDeploy107={...LESSONS.controlDeploy104,title:'Ancillary：控制者和已部署附属分别放装备',reviewDate:'2026-10-27',extras:[{...controlMember104('cu104a',32,{deployableItems:['shockMine']}),peripheral:'ancillary',name:'已部署Ancillary'}],question:'Ancillary部署后能否使用自己的装备？',answer:'与控制者同一技能激活，分别使用本身具有的装备；不受同步型的8寸运行距离限制。',instructions:'Idle后放置，控制者在(20,29)放中继器，远处Ancillary在(32,29)放地雷；两个库存分别减少1，命令末出现两个装备。'};
LESSONS.syncSupport107={...LESSONS.controlSupport106,title:'同步附属：各自黑客支援，独立目标',reviewDate:'2026-10-27',extras:LESSONS.controlSupport106.extras.filter(v=>v.id!=='cu104b').map(v=>v.id==='cu104a'?{...v,peripheral:'synchronized',name:'同步EVO'}:v),instructions:'整令强化反应：控制者选择左REM，同步EVO选择右REM。相同技能、各自范围和目标，结算后两REM均有ARO B2。'};
LESSONS.servantSensor107={...LESSONS.controlSensor104,title:'Servant：非医疗技能只用自己的能力',reviewDate:'2026-10-27',extras:[{...controlMember104('cu104a',24,{sensor:false}),peripheral:'servant',name:'无Sensor仆从'},LESSONS.controlDiscover104.extras[2]],instructions:'控制者有Sensor，已选择仆从没有。Idle后Sensor：控制者宣告，仆从按待机处理，不能借用控制者Sensor去发现右侧标记。控制者8/WIP20发现范围内标记。',dice:[8]};

LESSONS.fireteamNWI108={...LESSONS.fireteam30,title:'火力组：队长选择NWI，保留队长与加成',reviewDate:'2026-10-27',fireteam:true,terrain:[],first:'idle',source:'https://infinitythewiki.com/No_Wound_Incapacitation',positions:[[20,28],[18,29],[22,29],[18,31],[22,31],[20,20]],overrides:[{team:0,name:'NWI队长',nwi:true,hp:1,maxhp:1,arm:0,courage:true},{team:0,name:'Number 2甲',number2:true,courage:true},{team:0,name:'Number 2乙',number2:true,courage:true},{team:0,courage:true},{team:0,courage:true},{team:1,name:'蓝方射手',facing:90,bs:12,courage:true}],question:'队长受伤进入NWI时需要换队长吗？',answer:'先选择生存技能。NWI忽略昏迷Null标签，队长继续留组。若不启用、成为Null，Number 2是可选技能，玩家可选合法接任者或放弃；放弃解散。明确教学NWI和Number 2覆写。',instructions:'队长Idle→蓝方Combi ARO指定队长→主动Idle，骰8命中/20过保失败。选择NWI：不出现接任选择，Core仍5人L3，队长仍是NWI队长。',dice:[8,20]};
LESSONS.fireteamSuccession108={...LESSONS.fireteamNWI108,title:'火力组：拒绝NWI后，手动选择Number 2',source:'https://infinitythewiki.com/Number_2',instructions:'相同伤害后不启用NWI；从Number 2甲、乙中选择乙，不能默认替你选甲。剩余4人保持Core并重算L2，命令末检查新队长一致性。'};
LESSONS.fireteamDecline108={...LESSONS.fireteamSuccession108,title:'火力组：Number 2可放弃，立即解散',instructions:'相同伤害后不用NWI，再点击不使用Number 2。火力组解散，剩余成员全部失去加成；没有接任者。'};

